/*
 * App-private styles.
 *
 * `src/styles/**` is bundled into the custom element's shadow root, so nothing
 * in here can leak out to (or be reached from) the parent page. Rules that are
 * genuinely reusable elsewhere belong in `global.css`/`elements/*`; rules that
 * only make sense for this app belong here.
 */

truss-calibrator,
.truss-calibrator-root {
  display: block;
  color: var(--text-color-default);
  font-family: var(--font-body);
}

styles/global.css'
import './styles/local.css'
