import { render } from '@solidjs/testing-library'
import { describe, expect, it } from 'vitest'
import App from './App'

/**
 * T02.2 smoke test: proves the Vitest + jsdom + @solidjs/testing-library wiring
 * works end to end, independently of anything the app does.
 */
describe('component test harness', () => {
  it('renders a Solid component into jsdom', () => {
    const { getByText } = render(() => <App />)

    expect(getByText('Truss Calibrator')).toBeInTheDocument()
  })
})

/**
 * Core domain vocabulary.
 *
 * Everything the math, storage, and UI layers agree on lives here, so that the
 * PRD's invariants are stated once. Where an invariant can be carried by a type
 * it is, rather than being restated in a doc comment that nothing enforces.
 */

/* -------------------------------------------------------------------------- */
/* Persistence                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Namespaced local-storage keys.
 *
 * **Frozen.** Renaming these after the first ship orphans every stored printer
 * (PRD §7, §13.7). The `v1` segment is a coarse namespace: a future incompatible
 * change ships as `v2` alongside, leaving `v1` data readable rather than
 * silently reinterpreted.
 */
export const STORAGE_KEY_PRINTERS = 'truss-calibrator:v1:printers'
export const STORAGE_KEY_SETTINGS = 'truss-calibrator:v1:settings'

/** The only payload version this build can read (PRD §7). */
export const PAYLOAD_VERSION = 1

/**
 * A saved printer.
 *
 * `name` is the identity — trimmed, non-empty, unique case-insensitively — and
 * is deliberately the *only* identity, so exported JSON stays human-readable
 * and hand-editable (PRD §7, decision 5).
 */
export interface PrinterRecord {
  readonly name: string
  /** Finite and positive; derived from a quad calibration (PRD §7). */
  readonly extrapolationFactor: number
}

/** Envelope stored under {@link STORAGE_KEY_PRINTERS}. */
export interface PrintersPayload {
  readonly version: number
  readonly printers: readonly PrinterRecord[]
}

/** App state that is not printer data, and so is never exported (PRD §11.3). */
export interface SettingsState {
  /** When set, the prerequisites step is skipped on subsequent runs. */
  readonly skipPrerequisites: boolean
}

/** Envelope stored under {@link STORAGE_KEY_SETTINGS}. */
export interface SettingsPayload extends SettingsState {
  readonly version: number
}

export const DEFAULT_SETTINGS: SettingsState = { skipPrerequisites: false }

/* -------------------------------------------------------------------------- */
/* Calibration geometry                                                        */
/* -------------------------------------------------------------------------- */

/** The designed length of every beam, in millimetres (PRD §8.1). */
export const DESIGNED_LENGTH_MM = 140

/**
 * The four measured axes, in the order the guides introduce them.
 *
 * The order is load-bearing: the quad flow's measurement steps walk it, and the
 * fixtures in PRD §14.1 are expressed in it.
 */
export const AXES = ['X', 'Y', 'A', 'B'] as const

export type AxisId = (typeof AXES)[number]

/** Which set of caliper teeth produced a reading, for one axis (PRD §8.1). */
export const SIDES = ['outer', 'inner'] as const

export type MeasurementSide = (typeof SIDES)[number]

/** One caliper reading, in millimetres. */
export interface Measurement {
  readonly axis: AxisId
  readonly side: MeasurementSide
  readonly value: number
}

/**
 * The outer and inner reading for one axis, after parsing.
 *
 * This — not a bare list of eight numbers — is the unit the math layer consumes,
 * because the quad basis is *specifically* the X pair's average and a flat list
 * would let a caller substitute the wrong pair without the type noticing.
 */
export interface AxisPair {
  readonly axis: AxisId
  readonly outer: number
  readonly inner: number
}

/* -------------------------------------------------------------------------- */
/* Flows                                                                       */
/* -------------------------------------------------------------------------- */

/** The two calibration flows (PRD §9.3, §9.4). */
export const FLOWS = ['quad', 'single'] as const

export type FlowId = (typeof FLOWS)[number]

/** The axes a flow collects measurements for. */
export function axesForFlow(flow: FlowId): readonly AxisId[] {
  return flow === 'quad' ? AXES : ['X']
}

/**
 * A `Result` for operations that are *expected* to be able to fail.
 *
 * Storage and import are the reason this exists (PRD §12): site data can be
 * unavailable, a payload can be foreign or corrupt, an import file can be
 * subtly wrong. Those are ordinary outcomes the UI must render as messages, not
 * exceptions — and an exception thrown across a component boundary would escape
 * the degraded-mode handling that the whole storage design is built around
 * (T04.5). So the failure path is part of the return type.
 */

export type Result<T, E> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: E }

export function ok<T>(value: T): Result<T, never> {
  return { ok: true, value }
}

export function err<E>(error: E): Result<never, E> {
  return { ok: false, error }
}

export function isOk<T, E>(result: Result<T, E>): result is { ok: true; value: T } {
  return result.ok
}

export function isErr<T, E>(result: Result<T, E>): result is { ok: false; error: E } {
  return !result.ok
}

/** Read a result's value, substituting a fallback on failure. */
export function unwrapOr<T, E>(result: Result<T, E>, fallback: T): T {
  return result.ok ? result.value : fallback
}

/**
 * Run `fn`, converting a thrown value into a failed {@link Result}.
 *
 * Used at the boundary of third-party or host-controlled APIs (`localStorage`,
 * `FileReader`, `navigator.clipboard`) where "can throw" is part of the contract
 * and the caller's intent is to degrade rather than to propagate.
 */
export function attempt<T>(fn: () => T): Result<T, unknown> {
  try {
    return ok(fn())
  } catch (error) {
    return err(error)
  }
}

import { AXES, type AxisId, type FlowId, type MeasurementSide } from './types'

/**
 * The in-memory calibration draft (PRD §9.3, decision 2).
 *
 * One draft object is shared by every step of a flow, so Back is free and Next
 * only has to decide whether the step's gate is satisfied. It is deliberately
 * *not* persisted: closing or reloading restarts the flow at step 1 (decision 1,
 * decision 2's accepted limitation in §12).
 *
 * Values are held as **the text the user typed**, not as numbers. Parsing a
 * number and re-rendering it fights the keyboard mid-edit — `137.` and `137,0`
 * are legitimate intermediate states that a numeric round trip would rewrite
 * under the cursor. Parsing happens where a value is consumed (gates, math), so
 * a half-typed value blocks Next exactly as an empty one does while the text the
 * user typed is preserved for them to finish.
 */

/** The outer and inner readings for one axis, as typed. */
export interface AxisEntry {
  readonly outer: string
  readonly inner: string
}

export interface CalibrationDraft {
  /** Which flow this draft belongs to; fixed at flow entry. */
  readonly flow: FlowId
  /** Printer chosen in the quick flow's first step, if any. */
  readonly printerName: string | null
  /** All four axes are present regardless of flow, so step code needs no special cases. */
  readonly entries: Readonly<Record<AxisId, AxisEntry>>
  /** The slicer's current XY shrinkage value, as typed ('' until entered). */
  readonly currentSlicerPercent: string
}

const EMPTY_ENTRY: AxisEntry = { outer: '', inner: '' }

export function emptyEntry(): AxisEntry {
  return EMPTY_ENTRY
}

/**
 * A fresh draft for `flow`.
 *
 * Every flow entry point calls this, which is what makes "flow re-entry resets
 * the draft" (T15.3) a property of construction rather than something each entry
 * point has to remember.
 */
export function createDraft(flow: FlowId): CalibrationDraft {
  return {
    flow,
    printerName: null,
    entries: { X: EMPTY_ENTRY, Y: EMPTY_ENTRY, A: EMPTY_ENTRY, B: EMPTY_ENTRY },
    currentSlicerPercent: '',
  }
}

export function entryFor(draft: CalibrationDraft, axis: AxisId): AxisEntry {
  return draft.entries[axis]
}

/** Record one typed reading, leaving the other five/seven untouched. */
export function setMeasurement(
  draft: CalibrationDraft,
  axis: AxisId,
  side: MeasurementSide,
  text: string,
): CalibrationDraft {
  const current = draft.entries[axis]
  return {
    ...draft,
    entries: { ...draft.entries, [axis]: { ...current, [side]: text } },
  }
}

export function setCurrentSlicerPercent(draft: CalibrationDraft, text: string): CalibrationDraft {
  return { ...draft, currentSlicerPercent: text }
}

export function setPrinterName(draft: CalibrationDraft, name: string | null): CalibrationDraft {
  return { ...draft, printerName: name }
}

/**
 * Whether the user has entered *anything* at all.
 *
 * This is the trigger for the exit confirmation (PRD §9.3): it asks "has the
 * user done work that would be lost", so it counts non-blank text rather than
 * valid numbers. Someone who typed a reading and then wants to leave still gets
 * the confirmation even if what they typed is currently invalid — which is
 * exactly when losing it would sting most.
 */
export function hasAnyMeasurementText(draft: CalibrationDraft): boolean {
  return AXES.some((axis) => {
    const entry = draft.entries[axis]
    return entry.outer.trim() !== '' || entry.inner.trim() !== ''
  })
}

import type { CalibrationDraft } from './draft'
import type { FlowId } from './types'

/**
 * Flow-engine contracts (PRD §9).
 *
 * The engine itself lands in T15; these are the shapes it and every step agree
 * on, defined here so the two never drift apart.
 */

/** App-level destinations. There is no routing: every one of these is internal state (PRD §6.1). */
export const SCREENS = ['landing', 'flow', 'printers'] as const

export type ScreenId = (typeof SCREENS)[number]

/** Steps shared by both flows (PRD §9.2). */
export type CommonStepId = 'C1' | 'C2'

/** Quad (first-time) flow steps (PRD §9.3). */
export type QuadStepId = 'Q1' | 'Q2' | 'Q3' | 'Q4' | 'Q5' | 'Q6' | 'Q7' | 'Q8' | 'Q9'

/** Single (quick) flow steps (PRD §9.4). */
export type SingleStepId = 'S1' | 'S2' | 'S3' | 'S4' | 'S5' | 'S6' | 'S7'

export type StepId = CommonStepId | QuadStepId | SingleStepId

/**
 * Whether a step may be left, and if not, the reason to show and associate with
 * the gated control (T16.2).
 *
 * A blocked gate is always accompanied by a reason: a disabled Next with no
 * explanation is the most common way a gated flow becomes unsupportable.
 */
export interface GateStatus {
  readonly allowed: boolean
  readonly reason: string | null
}

export const OPEN_GATE: GateStatus = { allowed: true, reason: null }

export function blockedGate(reason: string): GateStatus {
  return { allowed: false, reason }
}

/**
 * One step of a flow.
 *
 * `title` is the step heading and, per PRD §6.4, the focus target on entry —
 * the view is replaced wholesale, so without moving focus there, keyboard and
 * screen-reader users are stranded on a destroyed element.
 *
 * `back === null` means "leaving the flow", which is what makes the Back control
 * and the Exit control the same code path.
 */
export interface StepDefinition {
  readonly id: StepId
  readonly flow: FlowId
  readonly title: string
  /** Evaluated against the shared draft; never mutates it. */
  readonly gate: (draft: CalibrationDraft) => GateStatus
  readonly next: StepId | null
  readonly back: StepId | null
}

/** Everything the exit rule needs to know about the current run. */
export interface FlowProgress {
  /** At least one measurement has been entered. */
  readonly hasMeasurements: boolean
  /** The flow's final step has been reached. */
  readonly isComplete: boolean
}

export type ExitDecision = 'leave' | 'confirm'

/**
 * PRD §9.3: confirm only once measurements exist and before the flow completes.
 *
 * Steps C1–C2 and the instructional steps exit without confirmation — nothing
 * has been measured, so there is nothing to lose. And once the flow is complete,
 * leaving is the flow's own success path and must not be second-guessed.
 */
export function exitDecision(progress: FlowProgress): ExitDecision {
  return progress.hasMeasurements && !progress.isComplete ? 'confirm' : 'leave'
}

/**
 * Number rounding, formatting, and parsing (PRD §8.2).
 *
 * Two rules drive everything here:
 *
 * 1. **Display is rounded half-up, not truncated.** The outline said truncate;
 *    the PRD deliberately departs from it, because truncation biases every
 *    displayed value *downward* and the displayed value is what the user retypes
 *    into their slicer. "Half-up" has a sign convention: it rounds a tie *away
 *    from zero*, so the rule has no directional bias on either side of zero.
 * 2. **Rounded values are for display only.** Computation always uses the full
 *    float. Nothing in this module is ever fed back into the math.
 */

/** Display precision per value, from PRD §8.2 and §13.1. */
export const FACTOR_PLACES = 10
export const RATIO_PLACES = 5
/** Settled at 3dp in T03.1; see PRD §13.1 for the reasoning. */
export const PERCENT_PLACES = 3
/** Calipers read to 0.01mm, which is the most a measurement can honestly claim. */
export const MEASUREMENT_PLACES = 2

/**
 * Scale `value` by a power of ten *through its decimal representation*.
 *
 * This is the crux of correct half-up rounding, and it is why `toFixed` and a
 * naive `value * 10 ** places` are both wrong. `1.005` is not representable in
 * binary: the nearest double is `1.00499999999999989…`, so `1.005 * 100` is
 * `100.49999999999999` and rounds *down*, when the decimal the user wrote clearly
 * rounds up. Interpolating the exponent into the shortest decimal string instead
 * makes the parser round `100.5` to the nearest double — which is exactly
 * `100.5`, since it is representable — so the tie is preserved and rounds up.
 */
function shiftExponent(value: number, exponent: number): number {
  const [mantissa, existing] = `${value}e`.split('e') as [string, string | undefined]
  const current = existing === undefined || existing === '' ? 0 : Number(existing)
  return Number(`${mantissa}e${current + exponent}`)
}

/**
 * Round to `places` decimal places, half away from zero.
 *
 * Non-finite input is returned unchanged rather than thrown on: callers that
 * reach here with `NaN` have a validation bug to display, not an exception to
 * handle. A value too large to scale (e.g. `1e21` at 2 places) is also returned
 * unchanged — its last decimal places are below the representable precision of
 * a double anyway, so rounding it is a no-op in exact terms.
 */
export function roundHalfUp(value: number, places: number): number {
  if (!Number.isInteger(places) || places < 0) {
    throw new RangeError(`places must be a non-negative integer, received ${places}`)
  }
  if (!Number.isFinite(value)) {
    return value
  }

  const scaled = shiftExponent(value, places)
  if (!Number.isFinite(scaled)) {
    return value
  }

  const rounded = Math.round(Math.abs(scaled))
  return shiftExponent(scaled < 0 ? -rounded : rounded, -places)
}

function formatPlaces(value: number, places: number): string {
  if (!Number.isFinite(value)) {
    return String(value)
  }
  return roundHalfUp(value, places).toFixed(places)
}

/** Extrapolation factor, 10dp (e.g. `1.0034215686`). */
export function formatFactor(value: number): string {
  return formatPlaces(value, FACTOR_PLACES)
}

/** Shrinkage compensation ratio, 5dp (e.g. `0.98188`). */
export function formatRatio(value: number): string {
  return formatPlaces(value, RATIO_PLACES)
}

/** Slicer-ready percentage, 3dp (e.g. `98.188`). */
export function formatPercent(value: number): string {
  return formatPlaces(value, PERCENT_PLACES)
}

/** A measurement or an average of measurements, at caliper resolution. */
export function formatMeasurement(value: number): string {
  return formatPlaces(value, MEASUREMENT_PLACES)
}

/* -------------------------------------------------------------------------- */
/* Parsing                                                                     */
/* -------------------------------------------------------------------------- */

export type NumberParseErrorCode = 'empty' | 'malformed'

export interface NumberParseError {
  readonly code: NumberParseErrorCode
  /** The offending text, so the caller can quote it back verbatim. */
  readonly text: string
}

export type ParsedNumber =
  | { readonly ok: true; readonly value: number }
  | { readonly ok: false; readonly error: NumberParseError }

/**
 * A complete decimal: optional sign, digits, and at most one decimal separator
 * that must be followed by digits.
 *
 * `5.` is *not* accepted even though JavaScript happily parses it, because it is
 * a half-typed value: accepting it would let a user advance past a field they
 * were still editing, which for the highest-risk screen in the product is the
 * wrong default. `.5` *is* accepted — it is unambiguous and complete.
 */
const DECIMAL_PATTERN = /^[+-]?(?:\d+(?:[.,]\d+)?|[.,]\d+)$/

/**
 * Parse user-entered decimal text, accepting either `,` or `.` as the separator.
 *
 * Note the accepted ambiguity: `1,234` parses as `1.234`, not as one thousand
 * two hundred and thirty-four. Thousands separators are not a thing in this
 * app's inputs (caliper readings run 133–139mm) and refusing every comma would
 * break the locale where `137,5` is how a millimetre is written, so the comma is
 * read as a decimal point and any resulting absurd value is caught by the
 * plausible-range *warning* rather than by a parse failure.
 */
export function parseNumber(text: string): ParsedNumber {
  const trimmed = text.trim()
  if (trimmed === '') {
    return { ok: false, error: { code: 'empty', text } }
  }
  if (!DECIMAL_PATTERN.test(trimmed)) {
    return { ok: false, error: { code: 'malformed', text } }
  }

  const normalized = trimmed.replace(',', '.')
  const value = Number(normalized)
  if (!Number.isFinite(value)) {
    // Unreachable for inputs matching the pattern, but a silent NaN escaping
    // into the math layer is exactly the failure this app exists to prevent.
    return { ok: false, error: { code: 'malformed', text } }
  }

  return { ok: true, value }
}

import { describe, expect, it } from 'vitest'
import {
  formatFactor,
  formatMeasurement,
  formatPercent,
  formatRatio,
  parseNumber,
  roundHalfUp,
} from './number'

describe('roundHalfUp', () => {
  /*
   * The PRD's tie fixture (§14.1, fixture B). 137.4625 / 140 is exactly
   * 0.981875 decimal, so this is a true half-way case at 5dp and pins the rule:
   * truncation would give 0.98187, half-up gives 0.98188.
   */
  it('rounds the fixture B tie up', () => {
    expect(roundHalfUp(0.981875, 5)).toBe(0.98188)
  })

  it('rounds other exact ties away from zero', () => {
    expect(roundHalfUp(0.5, 0)).toBe(1)
    expect(roundHalfUp(1.5, 0)).toBe(2)
    expect(roundHalfUp(2.25, 1)).toBe(2.3)
    expect(roundHalfUp(0.125, 2)).toBe(0.13)
  })

  it('rounds negative ties away from zero, so the rule has no sign bias', () => {
    expect(roundHalfUp(-0.5, 0)).toBe(-1)
    expect(roundHalfUp(-2.25, 1)).toBe(-2.3)
    expect(roundHalfUp(-1.005, 2)).toBe(-1.01)
  })

  /*
   * The float trap the PRD calls out explicitly. The nearest double to 1.005 is
   * 1.00499999999999989..., so `1.005 * 100` is 100.49999999999999 and a
   * multiply-then-round implementation gets this wrong. 2.675 and 8.475 are the
   * same trap reached through different binaries.
   */
  it('handles the 1.005 float trap the way a decimal calculator would', () => {
    expect(roundHalfUp(1.005, 2)).toBe(1.01)
    expect(roundHalfUp(2.675, 2)).toBe(2.68)
    expect(roundHalfUp(8.475, 2)).toBe(8.48)
    expect(roundHalfUp(9.935, 2)).toBe(9.94)
  })

  it('leaves values that need no rounding untouched', () => {
    expect(roundHalfUp(137.5, 10)).toBe(137.5)
    expect(roundHalfUp(0.9997272727, 10)).toBe(0.9997272727)
    expect(roundHalfUp(0, 5)).toBe(0)
    expect(roundHalfUp(-0, 5)).toBe(-0)
  })

  it('passes non-finite values through instead of throwing', () => {
    expect(Number.isNaN(roundHalfUp(Number.NaN, 5))).toBe(true)
    expect(roundHalfUp(Number.POSITIVE_INFINITY, 5)).toBe(Number.POSITIVE_INFINITY)
    expect(roundHalfUp(Number.NEGATIVE_INFINITY, 5)).toBe(Number.NEGATIVE_INFINITY)
  })

  it('rejects a nonsensical places argument loudly', () => {
    expect(() => roundHalfUp(1, -1)).toThrow(RangeError)
    expect(() => roundHalfUp(1, 1.5)).toThrow(RangeError)
  })

  it('survives extreme magnitudes', () => {
    // Beyond double precision: the requested places are not representable, so
    // the value must come back unchanged rather than as NaN or Infinity.
    expect(roundHalfUp(1e21, 2)).toBe(1e21)
    expect(roundHalfUp(5e-7, 3)).toBe(0)
    expect(roundHalfUp(5e-7, 10)).toBe(5e-7)
    expect(roundHalfUp(1e-21, 10)).toBe(0)
  })
})

describe('display formatters', () => {
  it('pads to a fixed number of places so digit count never shifts', () => {
    expect(formatFactor(1)).toBe('1.0000000000')
    expect(formatRatio(0.981875)).toBe('0.98188')
    expect(formatPercent(98.1875)).toBe('98.188')
    expect(formatMeasurement(137.5)).toBe('137.50')
  })

  it('matches the PRD worked fixtures', () => {
    // Fixture A: a degenerate quad yields F = 1 and R = 137.5/140.
    expect(formatRatio(137.5 / 140)).toBe('0.98214')
    expect(formatPercent((137.5 / 140) * 100)).toBe('98.214')

    // Fixture B: F = 137.4625 / 137.5, R = 137.4625 / 140.
    expect(formatFactor(137.4625 / 137.5)).toBe('0.9997272727')
    expect(formatRatio(137.4625 / 140)).toBe('0.98188')
    expect(formatPercent((137.4625 / 140) * 100)).toBe('98.188')
  })

  it('does not derive the percentage from the rounded ratio', () => {
    // 0.98187 * 100 (truncated ratio) would display 98.187; the full-precision
    // ratio must produce 98.188. This is the regression the PRD warns about.
    expect(formatPercent((137.4625 / 140) * 100)).not.toBe('98.187')
  })

  it('renders non-finite values as text rather than throwing', () => {
    expect(formatFactor(Number.NaN)).toBe('NaN')
    expect(formatRatio(Number.POSITIVE_INFINITY)).toBe('Infinity')
  })
})

describe('parseNumber', () => {
  it('accepts complete decimals with a point', () => {
    expect(parseNumber('137.5')).toEqual({ ok: true, value: 137.5 })
    expect(parseNumber('137')).toEqual({ ok: true, value: 137 })
    expect(parseNumber('0.01')).toEqual({ ok: true, value: 0.01 })
  })

  it('accepts a comma as the decimal separator', () => {
    expect(parseNumber('137,5')).toEqual({ ok: true, value: 137.5 })
    expect(parseNumber(',5')).toEqual({ ok: true, value: 0.5 })
  })

  it('accepts a leading sign so that negatives reach validation with a real value', () => {
    expect(parseNumber('-3')).toEqual({ ok: true, value: -3 })
    expect(parseNumber('+3.5')).toEqual({ ok: true, value: 3.5 })
  })

  it('trims surrounding whitespace but rejects interior whitespace', () => {
    expect(parseNumber('  137.5  ')).toEqual({ ok: true, value: 137.5 })
    expect(parseNumber('13 7,5').ok).toBe(false)
  })

  it('rejects empty input as its own reason', () => {
    expect(parseNumber('')).toEqual({ ok: false, error: { code: 'empty', text: '' } })
    expect(parseNumber('   ')).toEqual({ ok: false, error: { code: 'empty', text: '   ' } })
  })

  it('rejects half-typed values', () => {
    expect(parseNumber('5.')).toEqual({ ok: false, error: { code: 'malformed', text: '5.' } })
    expect(parseNumber('5,')).toEqual({ ok: false, error: { code: 'malformed', text: '5,' } })
    expect(parseNumber('.')).toEqual({ ok: false, error: { code: 'malformed', text: '.' } })
