import type { CalibrationDraft } from './draft'
import { formatFactor, formatMeasurement, formatRatio, parseNumber } from './number'
import {
  AXES,
  DESIGNED_LENGTH_MM,
  type AxisId,
  type AxisPair,
  type Measurement,
  type MeasurementSide,
} from './types'

/**
 * The calculation engine (PRD §8.1).
 *
 * Both flows are **one** computation with a different measurement basis:
 *
 *     R = F × (basis / 140)
 *
 * The guides phrase the quad flow as `v̄8 / 140` and the single flow as
 * `(v̄2 / 140) × F`. Those are algebraically identical because multiplication
 * commutes — which is exactly why they are dangerous: an implementation that
 * evaluates each flow in "its own" order from its own guide can drift, and the
 * drift is invisible, because both produce a plausible number near 0.98.
 *
 * So there is precisely one evaluation order here:
 *
 *     extrapolatedAverage = <the beam-spanning average for this flow>
 *     ratio               = extrapolatedAverage / 140
 *
 * The *only* flow-specific input is what that extrapolated average is:
 *
 *   - quad:   `v̄8` — a quad print needs no extrapolation, it *is* the four-axis
 *             measurement. (Note it deliberately does not route through
 *             `v̄X × (v̄8 / v̄X)`: that product is not bit-exact in floating point
 *             and would make the ratio depend on which flow computed it.)
 *   - single: `v̄2 × F` — the whole point of the stored factor.
 *
 * Rounded output is *reported alongside* the full-precision values by
 * {@link evaluateQuad} / {@link evaluateSingle}, never substituted for them, so
 * a caller cannot compute the percentage from a rounded ratio (PRD §8.2).
 */

/** The slicer's XY shrinkage default, offered as the starting value (PRD §10). */
export const DEFAULT_CURRENT_SLICER_PERCENT = 100

/* -------------------------------------------------------------------------- */
/* Reading a draft                                                             */
/* -------------------------------------------------------------------------- */

/** A slot that cannot be used yet, with the text that is currently in it. */
export interface PendingSlot {
  readonly axis: AxisId
  readonly side: MeasurementSide
  readonly text: string
}

/**
 * The result of reading a draft's measurements.
 *
 * `pending` is non-empty when any slot is empty, non-numeric, non-finite, or
 * ≤ 0 — the blocking rules of PRD §8.3. Reporting *which* slots are missing
 * (rather than a bare boolean) is what lets a step gate disable Next and name
 * what it is still waiting for.
 */
export type MeasurementsRead =
  | { readonly ok: true; readonly pairs: readonly AxisPair[]; readonly values: readonly number[] }
  | { readonly ok: false; readonly pending: readonly PendingSlot[] }

type SideRead =
  | { readonly ok: true; readonly value: number }
  | { readonly ok: false; readonly pending: PendingSlot }

function readSide(axis: AxisId, side: MeasurementSide, text: string): SideRead {
  const parsed = parseNumber(text)
  if (!parsed.ok || !(parsed.value > 0)) {
    return { ok: false, pending: { axis, side, text } }
  }
  return { ok: true, value: parsed.value }
}

/**
 * Read every requested axis, in order, returning either all of the measurements
 * or the exact set of slots still needed.
 *
 * All-or-nothing on purpose: a partially-read set would let a caller average
 * however many values happened to be valid, which is precisely the silent
 * arithmetic error this app exists to eliminate.
 */
export function readMeasurements(
  draft: CalibrationDraft,
  axes: readonly AxisId[],
): MeasurementsRead {
  const pending: PendingSlot[] = []
  const pairs: AxisPair[] = []
  const values: number[] = []

  for (const axis of axes) {
    const entry = draft.entries[axis]
    const outer = readSide(axis, 'outer', entry.outer)
    const inner = readSide(axis, 'inner', entry.inner)

    if (!outer.ok) pending.push(outer.pending)
    if (!inner.ok) pending.push(inner.pending)
    if (!outer.ok || !inner.ok) continue

    pairs.push({ axis, outer: outer.value, inner: inner.value })
    values.push(outer.value, inner.value)
  }

  if (pending.length > 0) {
    return { ok: false, pending }
  }
  return { ok: true, pairs, values }
}

/** Every measurement across a set of axes, flattened in axis-then-side order. */
export function measurementsOf(pairs: readonly AxisPair[]): readonly Measurement[] {
  const out: Measurement[] = []
  for (const pair of pairs) {
    out.push({ axis: pair.axis, side: 'outer', value: pair.outer })
    out.push({ axis: pair.axis, side: 'inner', value: pair.inner })
  }
  return out
}

/* -------------------------------------------------------------------------- */
/* Value-level math                                                            */
/* -------------------------------------------------------------------------- */

/** Arithmetic mean. An empty list yields `NaN`; completeness is a gate's job. */
export function average(values: readonly number[]): number {
  let sum = 0
  for (const value of values) {
    sum += value
  }
  return sum / values.length
}

/** The mean of one axis's two readings — the basis for both flows' averaging. */
export function pairAverage(pair: AxisPair): number {
  return average([pair.outer, pair.inner])
}

/** The mean of all readings across the given axes (8 for quad, 2 for single). */
export function meanOfPairs(pairs: readonly AxisPair[]): number {
  return average(measurementsOf(pairs).map((measurement) => measurement.value))
}

/** The quad flow's basis: the X beam's own average (PRD §8.1). */
export function quadBasisFromPairs(pairs: readonly AxisPair[]): number {
  const x = pairs.find((pair) => pair.axis === 'X')
  if (x === undefined) {
    throw new Error('quadBasisFromPairs requires an X pair')
  }
  return pairAverage(x)
}

/**
 * The printer's four-axis extrapolation factor: `v̄8 / v̄X` (PRD §8.1).
 *
 * This is the only flow-specific *division*, and the single flow never performs
 * it — it reads the stored result — which is what keeps the two flows from
 * disagreeing about what the factor means.
 */
export function quadFactorFromPairs(pairs: readonly AxisPair[]): number {
  return meanOfPairs(pairs) / quadBasisFromPairs(pairs)
}

/**
 * The one place a compensation ratio is produced: divide the extrapolated
 * average by the designed length. See the module comment for why nothing else
 * divides by 140.
 */
export function ratioFromExtrapolatedAverage(extrapolatedAverage: number): number {
  return extrapolatedAverage / DESIGNED_LENGTH_MM
}

/** `v̄8 / 140` for a complete quad measurement set. */
export function quadRatioFromPairs(pairs: readonly AxisPair[]): number {
  return ratioFromExtrapolatedAverage(meanOfPairs(pairs))
}

/**
 * The predicted quad-beam average from a single-beam print:
 * `v̄2 × F` (PRD §8.1).
 */
export function singleExtrapolatedAverage(pair: AxisPair, factor: number): number {
  return pairAverage(pair) * factor
}

/** `(v̄2 × F) / 140`, evaluated in the canonical order. */
export function singleRatio(pair: AxisPair, factor: number): number {
  return ratioFromExtrapolatedAverage(singleExtrapolatedAverage(pair, factor))
}

/**
 * `current slicer value × R`, at full precision (PRD §8.2, §10).
 *
 * The percentage is the one value the user transcribes, so it is computed from
 * the full-precision ratio every time it is shown — never from the rounded
 * ratio that sits next to it on screen.
 */
export function applyCurrentSlicerValue(currentPercent: number, ratio: number): number {
  return currentPercent * ratio
}

/* -------------------------------------------------------------------------- */
/* Draft-level entry points (T06.6)                                            */
/* -------------------------------------------------------------------------- */

/** Full-precision values paired with the rounded strings used to display them. */
export interface OutcomeDisplay {
  /** Mean of every reading (8 in quad, 2 in single). */
  readonly mean: string
  /** The flow's basis: `v̄X` in quad, `v̄2` in single. */
  readonly basis: string
  /** The extrapolation factor — measured in quad, stored in single. */
  readonly factor: string
  /** Shrinkage compensation ratio. */
  readonly ratio: string
}

interface OutcomeBase {
  readonly pairs: readonly AxisPair[]
  /** Mean of every reading. */
  readonly mean: number
  /** The flow's measurement basis. */
  readonly basis: number
  readonly factor: number
  /** The value divided by 140 (PRD §8.1's canonical order). */
  readonly extrapolatedAverage: number
  readonly ratio: number
  readonly display: OutcomeDisplay
}

export interface QuadOutcome extends OutcomeBase {
  readonly flow: 'quad'
}

export interface SingleOutcome extends OutcomeBase {
  readonly flow: 'single'
}

export type CalibrationOutcome = QuadOutcome | SingleOutcome

function displayFor(
  mean: number,
  basis: number,
  factor: number,
  ratio: number,
): OutcomeDisplay {
  return {
    mean: formatMeasurement(mean),
    basis: formatMeasurement(basis),
    factor: formatFactor(factor),
    ratio: formatRatio(ratio),
  }
}

/** Evaluate a complete quad draft, or `null` while any reading is missing. */
export function evaluateQuad(draft: CalibrationDraft): QuadOutcome | null {
  const read = readMeasurements(draft, AXES)
  if (!read.ok) {
    return null
  }

  const mean = meanOfPairs(read.pairs)
  const basis = quadBasisFromPairs(read.pairs)
  const factor = mean / basis
  const ratio = ratioFromExtrapolatedAverage(mean)

  return {
    flow: 'quad',
    pairs: read.pairs,
    mean,
    basis,
    factor,
    extrapolatedAverage: mean,
    ratio,
    display: displayFor(mean, basis, factor, ratio),
  }
}

/**
 * Evaluate a complete single draft against a stored factor, or `null` while
 * either reading is missing.
 *
 * The factor is passed in rather than looked up so that this stays pure and the
 * cross-flow equivalence property can be tested directly.
 */
export function evaluateSingle(draft: CalibrationDraft, factor: number): SingleOutcome | null {
  const read = readMeasurements(draft, ['X'])
  if (!read.ok) {
    return null
  }

  const pair = read.pairs[0]
  const mean = pairAverage(pair)
  const extrapolatedAverage = mean * factor
  const ratio = ratioFromExtrapolatedAverage(extrapolatedAverage)

  return {
    flow: 'single',
    pairs: read.pairs,
    mean,
    basis: mean,
    factor,
    extrapolatedAverage,
    ratio,
    display: displayFor(mean, mean, factor, ratio),
  }
}

/* -------------------------------------------------------------------------- */
/* Draft-level convenience (naming fixed by the build plan)                    */
/* -------------------------------------------------------------------------- */

/** `v̄X`, or `null` while the X readings are incomplete. */
export function quadBasis(draft: CalibrationDraft): number | null {
  const read = readMeasurements(draft, AXES)
  return read.ok ? quadBasisFromPairs(read.pairs) : null
}

/** `v̄8 / v̄X`, or `null` while any reading is incomplete. */
export function quadFactor(draft: CalibrationDraft): number | null {
  return evaluateQuad(draft)?.factor ?? null
}

/** `v̄8 / 140`, or `null` while any reading is incomplete. */
export function quadRatio(draft: CalibrationDraft): number | null {
  return evaluateQuad(draft)?.ratio ?? null
}

import { describe, expect, it } from 'vitest'
import { createDraft, setMeasurement, type CalibrationDraft } from './draft'
import {
  applyCurrentSlicerValue,
  average,
  evaluateQuad,
  evaluateSingle,
  meanOfPairs,
  pairAverage,
  quadBasis,
  quadFactor,
  quadFactorFromPairs,
  quadRatio,
  readMeasurements,
  singleExtrapolatedAverage,
  singleRatio,
} from './math'
import { AXES, type AxisId, type AxisPair } from './types'

/**
 * Golden fixtures from PRD §14.1.
 *
 * Every expected value below is **hand-computed in the comment above it**,
 * independently of the implementation. That is the whole point: a mis-averaged
 * or mis-extrapolated step still yields a plausible number near 0.98, so a test
 * that re-asserts the implementation's own arithmetic proves nothing.
 */

/** Fixture A — degenerate quad: every one of the eight readings is 137.50. */
const FIXTURE_A: Readonly<Record<AxisId, readonly [number, number]>> = {
  X: [137.5, 137.5],
  Y: [137.5, 137.5],
  A: [137.5, 137.5],
  B: [137.5, 137.5],
}

/** Fixture B — non-trivial factor; also the rounding-tie case. */
const FIXTURE_B: Readonly<Record<AxisId, readonly [number, number]>> = {
  X: [138.0, 137.0],
  Y: [137.0, 136.5],
  A: [138.2, 138.0],
  B: [137.6, 137.4],
}

function draftWith(flow: 'quad' | 'single', readings: Partial<Record<AxisId, readonly [number, number]>>): CalibrationDraft {
  let draft = createDraft(flow)
  for (const axis of AXES) {
    const pair = readings[axis]
    if (pair === undefined) continue
    draft = setMeasurement(draft, axis, 'outer', String(pair[0]))
    draft = setMeasurement(draft, axis, 'inner', String(pair[1]))
  }
  return draft
}

/* -------------------------------------------------------------------------- */
/* Fixture A                                                                   */
/* -------------------------------------------------------------------------- */

describe('fixture A — degenerate quad', () => {
  /*
   * All eight readings are 137.50.
   *   v̄8 = 8 × 137.50 / 8            = 137.50
   *   v̄X = (137.50 + 137.50) / 2     = 137.50
   *   F  = v̄8 / v̄X                   = 1.0 exactly
   *   R  = 137.50 / 140               = 0.982142857142857… → 5dp 0.98214
   *   at 100%: 98.214285714…         → 3dp 98.214
   */
  const outcome = evaluateQuad(draftWith('quad', FIXTURE_A))

  it('computes the factor as exactly 1', () => {
    expect(outcome).not.toBeNull()
    expect(outcome?.factor).toBe(1)
    expect(outcome?.display.factor).toBe('1.0000000000')
  })

  it('computes 137.50 / 140 and rounds it up-free at 5dp', () => {
    expect(outcome?.ratio).toBeCloseTo(0.982142857142857, 15)
    expect(outcome?.display.ratio).toBe('0.98214')
  })

  it('yields 98.214% at a current slicer value of 100', () => {
    const percent = applyCurrentSlicerValue(100, outcome!.ratio)
    expect(percent).toBeCloseTo(98.21428571428571, 12)
    expect(percent.toFixed(3)).toBe('98.214')
  })
})

/* -------------------------------------------------------------------------- */
/* Fixture B                                                                   */
/* -------------------------------------------------------------------------- */

describe('fixture B — non-trivial factor and the rounding tie', () => {
  /*
   * Readings, in AXES order (outer, inner):
   *   X 138.00 / 137.00 · Y 137.00 / 136.50 · A 138.20 / 138.00 · B 137.60 / 137.40
   *
   *   sum  = 138.00 + 137.00 + 137.00 + 136.50 + 138.20 + 138.00 + 137.60 + 137.40
   *        = 1099.70
   *   v̄8  = 1099.70 / 8              = 137.4625
   *   v̄X  = (138.00 + 137.00) / 2    = 137.50
   *   F   = 137.4625 / 137.50         = 0.999727272727… → 10dp 0.9997272727
   *   R   = 137.4625 / 140            = 0.981875 *exactly* → the tie case:
   *                                     half-up gives 0.98188, truncation 0.98187
   *   at 100%: 98.1875%               → 3dp 98.188
   */
  const outcome = evaluateQuad(draftWith('quad', FIXTURE_B))

  it('sums and averages all eight readings', () => {
    expect(outcome?.mean).toBeCloseTo(137.4625, 12)
    expect(outcome?.display.mean).toBe('137.46')
  })

  it('uses only the X pair for the basis', () => {
    expect(outcome?.basis).toBe(137.5)
  })

  it('computes the extrapolation factor and rounds it to 10dp', () => {
    expect(outcome?.factor).toBeCloseTo(137.4625 / 137.5, 15)
    expect(outcome?.display.factor).toBe('0.9997272727')
  })

  it('rounds the tie up to 0.98188, which pins the half-up rule', () => {
    expect(outcome?.ratio).toBeCloseTo(0.981875, 15)
    expect(outcome?.display.ratio).toBe('0.98188')
    expect(outcome?.display.ratio).not.toBe('0.98187')
  })

  it('yields 98.188% at a current slicer value of 100', () => {
    const percent = applyCurrentSlicerValue(100, outcome!.ratio)
    expect(percent.toFixed(3)).toBe('98.188')
    expect(percent.toFixed(2)).toBe('98.19')
  })
})

/* -------------------------------------------------------------------------- */
/* Fixture C — cross-flow equivalence                                          */
/* -------------------------------------------------------------------------- */

describe('fixture C — the single flow reproduces the quad flow', () => {
  /*
   * Fixture B's printer, used on a single-beam print measured 137.60 / 137.40 —
   * deliberately the same average as Fixture B's X pair.
   *
   *   v̄2              = (137.60 + 137.40) / 2 = 137.50  (= Fixture B's v̄X)
   *   v̄extrapolated   = 137.50 × F
   *   R                = 137.50 × F / 140
   *
   * With F at the full precision stored by the app, `137.50 × F` is Fixture B's
   * `v̄8` to the last bit, so R is the same double: 0.981875 → 0.98188.
   *
   * The factor is taken from the quad outcome rather than from the 10dp string,
   * because PRD §7 stores and computes with full precision; the 10dp form exists
   * only to be displayed.
   */
  const quad = evaluateQuad(draftWith('quad', FIXTURE_B))!
  const single = evaluateSingle(draftWith('single', { X: [137.6, 137.4] }), quad.factor)!

  it('averages only the two readings', () => {
    expect(single.mean).toBe(137.5)
    expect(single.display.mean).toBe('137.50')
  })

  it('extrapolates the two-value average by the stored factor', () => {
    expect(single.extrapolatedAverage).toBeCloseTo(137.4625, 12)
    expect(single.factor).toBe(quad.factor)
  })

  it('reproduces the quad flow ratio exactly', () => {
    expect(single.ratio).toBe(quad.ratio)
    expect(single.display.ratio).toBe('0.98188')
  })

  it('produces the same slicer-ready percentage as the quad flow', () => {
    const fromQuad = applyCurrentSlicerValue(100, quad.ratio)
    const fromSingle = applyCurrentSlicerValue(100, single.ratio)
    expect(fromSingle).toBe(fromQuad)
    expect(fromSingle.toFixed(3)).toBe('98.188')
  })

  /*
   * The transcription path, exercised honestly: a user who skipped saving (or
   * hit unavailable storage) can only copy the factor *as displayed*, at 10dp.
   * The ratio that follows lands within a whisker of the tie and may display its
   * last digit differently. That is a documented, quantified consequence of the
   * display rounding — not a correctness failure of the extrapolation model.
   */
  it('stays within the last displayed digit when the factor is transcribed from its 10dp display', () => {
    const transcribed = Number(quad.display.factor)
    const ratio = singleRatio({ axis: 'X', outer: 137.6, inner: 137.4 }, transcribed)

    expect(Math.abs(ratio - quad.ratio) / quad.ratio).toBeLessThan(1e-9)
  })
})

/* -------------------------------------------------------------------------- */
/* Property test generalising Fixture C (T06.5)                                */
/* -------------------------------------------------------------------------- */

/** Deterministic PRNG, so a failure is reproducible rather than a flake. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

describe('cross-flow equivalence property', () => {
  it('holds for randomly generated quad calibrations', () => {
    const random = mulberry32(0x7a1155)
    /** Plausible caliper readings: 133–139mm, inner a little under outer. */
    const reading = () => 133 + random() * 6
    const pair = (): AxisPair => {
      const outer = reading()
      return { axis: 'X', outer, inner: outer - 0.2 - random() * 1.6 }
    }

    for (let iteration = 0; iteration < 250; iteration += 1) {
      const pairs: AxisPair[] = AXES.map((axis) => ({ ...pair(), axis }))
      const factor = quadFactorFromPairs(pairs)
      const quadRatio = meanOfPairs(pairs) / 140

      // The single-flow basis is chosen to equal this calibration's X average,
      // which is precisely the condition under which the two must agree.
      const basis = quadBasisFromPairs(pairs)
      const single = singleRatio({ axis: 'X', outer: basis, inner: basis }, factor)

      expect(Math.abs(single - quadRatio) / quadRatio).toBeLessThan(1e-12)
    }
  })
})

/* -------------------------------------------------------------------------- */
/* Reading drafts                                                              */
/* -------------------------------------------------------------------------- */

describe('readMeasurements', () => {
  it('reports every missing slot rather than averaging what is present', () => {
    const draft = setMeasurement(createDraft('quad'), 'X', 'outer', '137.5')
    const read = readMeasurements(draft, AXES)

    expect(read.ok).toBe(false)
    if (!read.ok) {
      expect(read.pending.map((slot) => `${slot.axis}.${slot.side}`)).toEqual([
        'X.inner',
        'Y.outer',
        'Y.inner',
        'A.outer',
        'A.inner',
        'B.outer',
        'B.inner',
      ])
    }
  })

  it('treats zero, negatives, garbage, and half-typed text as blocking', () => {
    let draft = createDraft('single')
    draft = setMeasurement(draft, 'X', 'outer', '0')
    draft = setMeasurement(draft, 'X', 'inner', '137.')

    const read = readMeasurements(draft, ['X'])
    expect(read.ok).toBe(false)
    if (!read.ok) {
      expect(read.pending).toEqual([
        { axis: 'X', side: 'outer', text: '0' },
        { axis: 'X', side: 'inner', text: '137.' },
      ])
    }
  })

  it('accepts a comma decimal and presents the values in axis-then-side order', () => {
    let draft = createDraft('single')
    draft = setMeasurement(draft, 'X', 'outer', '137,60')
    draft = setMeasurement(draft, 'X', 'inner', '137,40')

    const read = readMeasurements(draft, ['X'])
    expect(read.ok).toBe(true)
    if (read.ok) {
      expect(read.values).toEqual([137.6, 137.4])
      expect(read.pairs).toEqual([{ axis: 'X', outer: 137.6, inner: 137.4 }])
    }
  })

  it('does not confuse one axis with another', () => {
    // Distinguishable values per axis: averaging the wrong pair cannot pass.
    const readings: Record<AxisId, readonly [number, number]> = {
      X: [138.0, 137.0],
      Y: [137.0, 136.5],
      A: [138.2, 138.0],
      B: [137.6, 137.4],
    }
    const draft = draftWith('quad', readings)
    const read = readMeasurements(draft, AXES)

    expect(read.ok).toBe(true)
    if (read.ok) {
      expect(read.pairs.map((p) => pairAverage(p))).toEqual([137.5, 136.75, 138.1, 137.5])
      expect(quadBasisFromPairs(read.pairs)).toBe(137.5)
    }
  })
})

/* -------------------------------------------------------------------------- */
/* Draft-level entry points                                                    */
/* -------------------------------------------------------------------------- */

describe('draft-level entry points', () => {
  it('return null while any reading is incomplete', () => {
    const partial = setMeasurement(createDraft('quad'), 'X', 'outer', '137.5')
    expect(evaluateQuad(partial)).toBeNull()
    expect(quadBasis(partial)).toBeNull()
    expect(quadFactor(partial)).toBeNull()
    expect(quadRatio(partial)).toBeNull()
  })

  it('agree with the pair-level functions on a complete draft', () => {
    const draft = draftWith('quad', FIXTURE_B)
    const outcome = evaluateQuad(draft)!

    expect(quadBasis(draft)).toBe(outcome.basis)
    expect(quadFactor(draft)).toBe(outcome.factor)
    expect(quadRatio(draft)).toBe(outcome.ratio)
  })

  it('expose full precision next to the display strings from one call', () => {
    const outcome = evaluateQuad(draftWith('quad', FIXTURE_B))!

    // The strings are rounded; the numbers are not. Computing from the strings
    // would give 98.187 at 3dp, so they are demonstrably different objects.
    expect(outcome.display.ratio).toBe('0.98188')
    expect(applyCurrentSlicerValue(100, outcome.ratio).toFixed(3)).toBe('98.188')
    expect(applyCurrentSlicerValue(100, Number(outcome.display.ratio)).toFixed(3)).toBe('98.188')
    expect(outcome.ratio).not.toBe(Number(outcome.display.ratio))
  })
})

describe('the two algebraic formulations agree', () => {
  /*
   * PRD §8.1 notes the guides' phrasings are equivalent: `v̄8 / 140` and
   * `(v̄X / 140) × F`. The implementation uses the "extrapolated average first"
   * order everywhere; this pins that the other order would not have changed the
   * answer, so a future reader does not "simplify" one into the other and
   * silently change behaviour.
   */
  it('evaluates F × (basis / 140) to the same value as (F × basis) / 140', () => {
    const outcome = evaluateQuad(draftWith('quad', FIXTURE_B))!
    const alternative = outcome.factor * (outcome.basis / 140)

    expect(Math.abs(alternative - outcome.ratio) / outcome.ratio).toBeLessThan(1e-12)
  })
})

describe('singleExtrapolatedAverage', () => {
  it('multiplies the two-value average by the factor', () => {
    expect(singleExtrapolatedAverage({ axis: 'X', outer: 137.6, inner: 137.4 }, 1.0034215686)).toBeCloseTo(
      137.5 * 1.0034215686,
      12,
    )
  })

  it('is a no-op for a factor of exactly 1', () => {
    expect(singleExtrapolatedAverage({ axis: 'X', outer: 137.5, inner: 137.5 }, 1)).toBe(137.5)
  })
})

describe('average', () => {
  it('is the arithmetic mean', () => {
    expect(average([1, 2, 3, 4])).toBe(2.5)
    expect(average([137.5])).toBe(137.5)
  })

  it('is order-independent, so axis order cannot change a result', () => {
    const values = [138.0, 137.0, 137.0, 136.5, 138.2, 138.0, 137.6, 137.4]
    expect(average(values)).toBeCloseTo(average([...values].reverse()), 12)
  })

  it('yields NaN rather than throwing on an empty list', () => {
    expect(Number.isNaN(average([]))).toBe(true)
  })
})

