    std::string variant_string;

    if (extruder_type > etMaxExtruderType) {

      BOOST_LOG_TRIVIAL(error) << __FUNCTION__ << boost::format(", unsupported
ExtruderType=%1%")%extruder_type;
        ...

...
        //extruder_type = etDirectDrive;

  return variant_string;
    }
    auto nozzle_volume_types =
get_valid_nozzle_volume_type();
    if (nozzle_volume_types.count(nozzle_volume_type) == 0) {

    BOOST_LOG_TRIVIAL(error) << __FUNCTION__ << boost::format(", unsupported
NozzleVolumeType=%1%")%nozzle_volume_type;
        //extruder_type =
etDirectDrive;
        return variant_string;
