&extruder_ams_count)
{
...

...
    std::vector<std::string> extruder_ams_count_str;

for (size_t i = 0; i < extruder_ams_count.size(); ++i) {

std::ostringstream oss;
        const auto &item = extruder_ams_count[i];
        for (auto it =
item.begin(); it != item.end(); ++it) {
            oss << it->first << "#" <<
