            if (std::next(it) != item.end()) {
                oss
<< "|";
            }
        }

extruder_ams_count_str.push_back(oss.str());
    }
    return extruder_ams_count_str;
}

// Maps a full extruder variant
string such as "Direct Drive High Flow" to its
// NozzleVolumeType: the
extruder-type prefix is stripped, the remainder is trimmed
// and looked up as a
volume-type name. Returns nvtHybrid when the string cannot
// be
parsed.
NozzleVolumeType convert_to_nvt_type(const std::string &variant_str) {
...

...
    const auto
&ext_types = ConfigOptionEnum<ExtruderType>::get_enum_names();

    auto trim =
[](std::string &s) {
        s.erase(s.find_last_not_of(" \t\r\n") + 1);

s.erase(0, s.find_first_not_of(" \t\r\n"));
    };

    for (auto ext_type : ext_types)
{
        size_t pos = variant_str.find(ext_type);
        if (pos ==
std::string::npos)
            continue;

        std::string result = variant_str;

  result.erase(pos, ext_type.size());
        trim(result);

        auto iter
= s_keys_map_NozzleVolumeType.find(result);
        if (iter !=
s_keys_map_NozzleVolumeType.end())
            return NozzleVolumeType(iter->second);
    }


return nvtHybrid;
}

// Parses the extruder_nozzle_stats option: one
"|"-separated token list per
// extruder, each token
// "<volume_type_name>#<count>".
...

...
Empty string => no per-type stats for that
extruder.
std::vector<std::map<NozzleVolumeType, int>> get_extruder_nozzle_stats(const std::vector<std::string> &strs)
{

   std::vector<std::map<NozzleVolumeType, int>> extruder_nozzle_counts;
    for
(const std::string &str : strs) {
        std::map<NozzleVolumeType, int>
nozzle_count_map;
        if (str.empty()) {

extruder_nozzle_counts.emplace_back(nozzle_count_map);
            continue;
        }

std::vector<std::string> nozzle_infos;
        boost::algorithm::split(nozzle_infos, str,
boost::algorithm::is_any_of("|"));
        for (auto &nozzle_info : nozzle_infos)
{
            std::vector<std::string> attr;

boost::algorithm::split(attr, nozzle_info, boost::algorithm::is_any_of("#"));
            // Guard
against malformed device/project data: skip tokens without a "<type>#<count>"
    ...

...
    // shape or with an unknown volume-type key instead of throwing (.at) or
reading attr[1]
            // out of bounds. Corrupt tokens are dropped and
logged; the rest still parse.
            if (attr.size() < 2) {

BOOST_LOG_TRIVIAL(warning) << "get_extruder_nozzle_stats: skipping malformed token
'" << nozzle_info << "'";
                continue;
            }

auto it = s_keys_map_NozzleVolumeType.find(attr[0]);
            if (it ==
s_keys_map_NozzleVolumeType.end()) {
                BOOST_LOG_TRIVIAL(warning) <<
"get_extruder_nozzle_stats: skipping unknown nozzle volume type '" << attr[0] <<
"'";
                continue;
            }
            NozzleVolumeType
volume_type = NozzleVolumeType(it->second);
            int              nozzle_count =
std::atoi(attr[1].c_str());
            nozzle_count_map[volume_type] =
nozzle_count;
        }
...

...
        extruder_nozzle_counts.emplace_back(nozzle_count_map);

}
    return extruder_nozzle_counts;
}

std::vector<std::string>
save_extruder_nozzle_stats_to_string(const std::vector<std::map<NozzleVolumeType, int>>
&extruder_nozzle_stats)
{
    std::vector<std::string> extruder_nozzle_count_str;

for (size_t idx = 0; idx < extruder_nozzle_stats.size(); ++idx) {

std::ostringstream oss;
        const auto        &item = extruder_nozzle_stats[idx];

       for (auto it = item.begin(); it != item.end(); ++it) {
            oss
<< get_nozzle_volume_type_string(it->first) << "#" << it->second;
            if
(std::next(it) != item.end())
                oss << "|";
        }

extruder_nozzle_count_str.emplace_back(oss.str());
    }
    return
extruder_nozzle_count_str;
}

static void assign_printer_technology_to_unknown(t_optiondef_map
...

...
&options, PrinterTechnology printer_technology)
{
    for (std::pair<const
t_config_option_key, ConfigOptionDef> &kvp : options)
        if
(kvp.second.printer_technology == ptUnknown)
            kvp.second.printer_technology =
printer_technology;
}

