        std::string extention;
        if
(config.has("thumbnails_format")) {
            if (const ConfigOptionDef* opt =
config.def()->get("thumbnails_format")) {
                extention =
opt->enum_values.at(config.option("thumbnails_format")->getInt());
            }
        }

        std::string
thumbnails_str = config.opt_string("thumbnails");
        auto [thumbnails_list,
errors] = GCodeThumbnails::make_and_check_thumbnail_list(thumbnails_str,
extention);

        if (errors != enum_bitmask<ThumbnailError>()) {

std::string error_str = "\n" + Slic3r::format("Invalid value provided for parameter
%1%: %2%", "thumbnails", thumbnails_str);
            error_str +=
GCodeThumbnails::get_error_string(errors);
            throw
BadOptionValueException(error_str);
        }
            ...

...
        if (!thumbnails_list.empty()) {
            const auto&
extentions = ConfigOptionEnum<GCodeThumbnailsFormat>::get_enum_names();

thumbnails_str.clear();
            for (const auto& [ext, size] :
thumbnails_list)
                thumbnails_str += Slic3r::format("%1%x%2%/%3%, ", size.x(),
size.y(), extentions[int(ext)]);

thumbnails_str.resize(thumbnails_str.length() - 2);

            config.set_key_value("thumbnails", new
ConfigOptionString(thumbnails_str));
        }
    }

    if
(config.has("wiping_volumes_matrix") && !config.has("wiping_volumes_use_custom_matrix")) {
        // This is
apparently some pre-2.7.3 config, where the wiping_volumes_matrix was always
used.
        // The 2.7.3 introduced an option to use defaults derived from
config. In case the matrix
        // contains only default values, switch it to
default behaviour. The default values
        // were zeros on the diagonal and 140
...

...
otherwise.
        std::vector<double> matrix =
config.opt<ConfigOptionFloats>("wiping_volumes_matrix")->values;
        int num_of_extruders =
int(std::sqrt(matrix.size()) + 0.5);
        int i = -1;
        bool custom = false;

for (int j = 0; j < int(matrix.size()); ++j) {
            if (j %
num_of_extruders == 0)
                ++i;
            if (i != j % num_of_extruders &&
!is_approx(matrix[j], 140.)) {
                custom = true;
                break;

          }
        }

config.set_key_value("wiping_volumes_use_custom_matrix", new ConfigOptionBool(custom));
    }
}

