// Regathers a vector option's values through per-slot source indices (one input
index per
// output slot). Out-of-range indices keep the first value, matching
get_at's fallback.
template<typename OptType, typename ValueType>
static void
gather_option_values(const char *caller, const std::string &key, OptType *opt,
const std::vector<int> &slot_param_indices)
{
    if (!opt || opt->values.empty())
{
...

...
        BOOST_LOG_TRIVIAL(warning) << caller << boost::format(", Line %1%:
option %2% not found or empty, skipping")%__LINE__%key;
        return;
    }

std::vector<ValueType> new_values;

new_values.reserve(slot_param_indices.size());
    for (int idx : slot_param_indices) {
        if (idx < 0 ||
static_cast<size_t>(idx) >= opt->values.size()) {
            BOOST_LOG_TRIVIAL(warning) <<
caller << boost::format(", Line %1%: option %2% slot index %3% out of range,
keeping first value")%__LINE__%key%idx;

new_values.emplace_back(opt->values.front());
        }
        else

new_values.emplace_back(opt->values[idx]);
    }
    opt->values = std::move(new_values);
}

