std::to_string(cfg.enforce_support_layers));
            //return "Spiral vase mode is not compatible with
support";
        }
    }

    // extrusion widths
    {
        double
max_nozzle_diameter = 0.;
        double min_nozzle_diameter =
std::numeric_limits<double>::max();
...

...
        for (double dmr : cfg.nozzle_diameter.values)
        {

 max_nozzle_diameter = std::max(max_nozzle_diameter, dmr);

min_nozzle_diameter = std::min(min_nozzle_diameter, dmr);
        }
        const char
*widths[] = {
            "outer_wall_line_width",

"inner_wall_line_width",
            "sparse_infill_line_width",

"internal_solid_infill_line_width",
            "bridge_line_width",

"top_surface_line_width",
            "support_line_width",
            "initial_layer_line_width",

           "skin_infill_line_width",

"skeleton_infill_line_width"};
        for (size_t i = 0; i < sizeof(widths) / sizeof(widths[i]); ++ i) {

       std::string key(widths[i]);
            double abs_width =
cfg.get_abs_value(key, max_nozzle_diameter);
            double allowed_max = (key ==
"bridge_line_width") ? min_nozzle_diameter : MAX_LINE_WIDTH_MULTIPLIER *
...

...
max_nozzle_diameter;
            if (abs_width > allowed_max) {
                if (key ==
"bridge_line_width")
                    error_message.emplace(key, L("Bridge line
width must not exceed nozzle diameter: ") + std::to_string(abs_width));

       else
                    error_message.emplace(key, L("too large line
width ") + std::to_string(abs_width));
                //return std::string("Too
Large line width: ") + key;
            }
        }
    }

    // Out of range
validation of numeric values.
    for (const std::string &opt_key : cfg.keys()) {

       const ConfigOption      *opt    = cfg.optptr(opt_key);

assert(opt != nullptr);
        const ConfigOptionDef   *optdef =
print_config_def.get(opt_key);
        assert(optdef != nullptr);
        bool out_of_range = false;

     switch (opt->type()) {
        case coFloat:
        case coPercent:

  case coFloatOrPercent:
        {
            auto *fopt = static_cast<const
...

...
ConfigOptionFloat*>(opt);
            out_of_range =
!optdef->is_value_valid(fopt->value);
            break;
        }
        case coFloats:
        case
coPercents:
            for (double v : static_cast<const
ConfigOptionVector<double>*>(opt)->values)
                if (!optdef->is_value_valid(v)) {

     out_of_range = true;
                    break;
                }

   break;
        case coInt:
        {
            auto *iopt =
static_cast<const ConfigOptionInt*>(opt);
            out_of_range =
!optdef->is_value_valid(iopt->value);
            break;
        }
        case coInts:
            for
(int v : static_cast<const ConfigOptionVector<int>*>(opt)->values)

 if (!optdef->is_value_valid(v)) {
                    out_of_range = true;

                break;
                }
            break;
        default:;

      }
        if (out_of_range) {
            if (error_message.find(opt_key)
== error_message.end())
...

...
                error_message.emplace(opt_key,
opt->serialize() + L(" not in range ") +"[" + std::to_string(optdef->min) + "," +
std::to_string(optdef->max) + "]");
            //return std::string("Value out of
range: " + opt_key);
        }
    }

    // Mixed-color (混色) parameter
validation.
    {
        const auto &is_mixed       = cfg.filament_is_mixed.values;

 const auto &comp_strs      = cfg.filament_mixed_components.values;

const auto &ratio_strs     = cfg.filament_mixed_sublayer_ratios.values;

const auto &gradient_flags = cfg.filament_mixed_gradient.values;
        const auto
&range_strs     = cfg.filament_mixed_gradient_range.values;
        const auto
&curve_strs     = cfg.filament_mixed_gradient_curve.values;


std::map<std::string, std::string> mixed_errors = validate_mixed_filament_params(
...

...
  is_mixed, comp_strs, ratio_strs, gradient_flags,
            range_strs,
curve_strs);
        for (const auto &kv : mixed_errors)
            if
(error_message.find(kv.first) == error_message.end())

error_message.emplace(kv.first, kv.second);
    }

    // The configuration is valid.
    return
error_message;
}

