Polygons get_bed_excluded_area(const PrintConfig& cfg)
{
    const Pointfs
exclude_area_points = cfg.bed_exclude_area.values;

    Polygon exclude_poly;
    for
(int i = 0; i < exclude_area_points.size(); i++) {
        auto pt =
exclude_area_points[i];
        exclude_poly.points.emplace_back(scale_(pt.x()),
scale_(pt.y()));
    }

    exclude_poly.make_counter_clockwise();

    return
{exclude_poly};
}

Polygon get_bed_shape_with_excluded_area(const PrintConfig& cfg, bool
use_share)
{
    Polygon bed_poly;
    bed_poly.points = get_bed_shape(cfg,
use_share);


    Polygons exclude_polys = get_bed_excluded_area(cfg);
    auto tmp =
diff({ bed_poly }, exclude_polys);
    if (!tmp.empty()) bed_poly = tmp[0];

return bed_poly;
}
