import { namesMatch, normalizeName } from '../domain/printer'
import { PAYLOAD_VERSION, type PrinterRecord } from '../domain/types'
import { checkPrintersPayload, type SchemaIssue } from './schema'

/**
 * Export and import (PRD §11.1–§11.3).
 *
 * Three rules shape this module:
 *
 * 1. **Full precision in the file.** The display formatters round to 10dp; a
 *    factor written at 10dp would be degraded a little on *every* round trip,
 *    silently, and the user would never see it happen. `JSON.stringify` writes
 *    the shortest representation that reads back as the identical double, which
 *    is exactly the requirement (T10.2).
 * 2. **Import is all-or-nothing.** Invalid JSON, an unexpected shape, an
 *    unsupported version, or any unusable record refuses the whole file with a
 *    specific reason. A half-applied import is worse than a refused one, because
 *    the user cannot tell which half landed.
 * 3. **Merge is add-only; existing values always win.** Conflicts are counted and
 *    named. The accepted consequence — an older backup cannot overwrite damaged
 *    current data without deleting the conflicting records first — is the UI's
 *    job to state (T23), not something to paper over here.
 */

/** Printer data only; the prerequisites flag is app state (PRD §11.3). */
export interface ExportShape {
  readonly version: number
  readonly printers: readonly PrinterRecord[]
}

/**
 * Refusal ceiling, checked before the file is read into memory.
 *
 * A record is under a hundred bytes of JSON, so even ten thousand printers sit
 * well under a megabyte; anything larger is the wrong file. Refusing on `size`
 * first means a mis-picked 2GB file is rejected without reading it.
 */
export const MAX_IMPORT_BYTES = 5 * 1024 * 1024

export function serializePrinters(printers: readonly PrinterRecord[]): string {
  const payload: ExportShape = {
    version: PAYLOAD_VERSION,
    printers: printers.map((record) => ({
      name: record.name,
      extrapolationFactor: record.extrapolationFactor,
    })),
  }
  // Indented, because the file is meant to be hand-editable and diffable.
  return JSON.stringify(payload, null, 2)
}

function pad(value: number): string {
  return String(value).padStart(2, '0')
}

/** `truss-printers-YYYY-MM-DD.json`, dated in the user's own timezone. */
export function exportFilename(now: Date = new Date()): string {
  const date = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`
  return `truss-printers-${date}.json`
}

/* -------------------------------------------------------------------------- */
/* Import                                                                      */
/* -------------------------------------------------------------------------- */

/** A specific reason the import was refused (PRD §11.2). */
export type ImportRefusal =
  | { readonly kind: 'too-large'; readonly bytes: number; readonly limit: number }
  | { readonly kind: 'invalid-json'; readonly detail: string }
  | { readonly kind: 'not-an-object'; readonly detail: string }
  | { readonly kind: 'unsupported-version'; readonly detail: string }
  | { readonly kind: 'malformed'; readonly detail: string }
  | { readonly kind: 'invalid-record'; readonly detail: string }

export interface ImportMerge {
  readonly ok: true
  /** The complete list to store: the existing records, then the added ones. */
  readonly merged: readonly PrinterRecord[]
  /** Names added, in file order. */
  readonly added: readonly string[]
  /** Names skipped because the name already existed, in file order. */
  readonly skipped: readonly string[]
}

export type ImportOutcome = ImportMerge | { readonly ok: false; readonly refusal: ImportRefusal }

/** Map a payload-schema issue onto the matching refusal, one-to-one. */
function refusalForIssue(issue: SchemaIssue, detail: string): ImportRefusal {
  switch (issue) {
    case 'not-an-object':
      return { kind: 'not-an-object', detail }
    case 'unsupported-version':
      return { kind: 'unsupported-version', detail }
    case 'malformed':
      return { kind: 'malformed', detail }
    case 'invalid-record':
      return { kind: 'invalid-record', detail }
  }
}

/**
 * Validate and merge a file's text into the existing records.
 *
 * Pure: it computes the merged list and changes nothing, so the caller decides
 * when to commit (and the same function serves the tests without a store).
 *
 * A name repeated *within* the file is treated as a conflict rather than as an
 * invalid file: uniqueness is a merge concern, and the first occurrence is the
 * one that wins — the same rule the user is being told about. It is reported in
 * `skipped` so the count the UI shows accounts for it.
 */
export function mergePrinters(text: string, existing: readonly PrinterRecord[]): ImportOutcome {
  if (text.length > MAX_IMPORT_BYTES) {
    return {
      ok: false,
      refusal: { kind: 'too-large', bytes: text.length, limit: MAX_IMPORT_BYTES },
    }
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(text) as unknown
  } catch (error) {
    return {
      ok: false,
      refusal: { kind: 'invalid-json', detail: error instanceof Error ? error.message : 'Unreadable.' },
    }
  }

  const checked = checkPrintersPayload(parsed)
  if (!checked.ok) {
    return { ok: false, refusal: refusalForIssue(checked.issue, checked.detail) }
  }

  const merged: PrinterRecord[] = [...existing]
  const added: string[] = []
  const skipped: string[] = []

  for (const record of checked.value.printers) {
    const name = normalizeName(record.name)
    if (merged.some((candidate) => namesMatch(candidate.name, name))) {
      skipped.push(name)
      continue
    }
    const stored: PrinterRecord = { name, extrapolationFactor: record.extrapolationFactor }
    merged.push(stored)
    added.push(name)
  }

  return { ok: true, merged, added, skipped }
}

/** Whether a file of `bytes` is too large to consider, for the pre-read check. */
export function isOversized(bytes: number): boolean {
  return bytes > MAX_IMPORT_BYTES
}

import { describe, expect, it } from 'vitest'
import { PAYLOAD_VERSION, type PrinterRecord } from '../domain/types'
import { checkPrintersPayload } from './schema'
import {
  exportFilename,
  isOversized,
  MAX_IMPORT_BYTES,
  mergePrinters,
  serializePrinters,
} from './transfer'

const X1C: PrinterRecord = { name: 'X1C', extrapolationFactor: 1.0034215686 }
const VORON: PrinterRecord = { name: 'Voron 2.4', extrapolationFactor: 0.9987272727 }

/** Assert a refusal and hand back its specific kind. */
function refusal(text: string, existing: readonly PrinterRecord[] = []) {
  const outcome = mergePrinters(text, existing)
  expect(outcome.ok).toBe(false)
  if (outcome.ok) {
    throw new Error('expected a refusal')
  }
  return outcome.refusal
}

describe('serializePrinters', () => {
  it('produces the PRD shape', () => {
    const parsed = JSON.parse(serializePrinters([X1C])) as unknown

    expect(parsed).toEqual({
      version: PAYLOAD_VERSION,
      printers: [{ name: 'X1C', extrapolationFactor: 1.0034215686 }],
    })
  })

  it('writes full precision, never the 10dp display value', () => {
    // 137.4625 / 137.5 has no short decimal form; the displayed 10dp value would
    // silently degrade the factor on every round trip (T10.2).
    const factor = 137.4625 / 137.5
    const text = serializePrinters([{ name: 'X1C', extrapolationFactor: factor }])
    const parsed = JSON.parse(text) as { printers: { extrapolationFactor: number }[] }

    expect(parsed.printers[0].extrapolationFactor).toBe(factor)
    expect(text).not.toContain('0.9997272727')
  })

  it('round-trips an awkward double exactly', () => {
    const factor = 0.1 + 0.2
    const text = serializePrinters([{ name: 'X1C', extrapolationFactor: factor }])
    const parsed = JSON.parse(text) as { printers: { extrapolationFactor: number }[] }

    expect(parsed.printers[0].extrapolationFactor).toBe(factor)
  })

  it('is indented so the file stays hand-editable', () => {
    expect(serializePrinters([X1C])).toContain('\n  "printers"')
  })

  it('excludes the prerequisites flag, which is app state', () => {
    expect(serializePrinters([X1C])).not.toContain('skipPrerequisites')
  })

  it('writes an empty list as a valid empty payload', () => {
    expect(checkPrintersPayload(JSON.parse(serializePrinters([]))).ok).toBe(true)
  })
})

describe('exportFilename', () => {
  it('is truss-printers-YYYY-MM-DD.json', () => {
    expect(exportFilename(new Date(2026, 8, 16))).toBe('truss-printers-2026-09-16.json')
  })

  it('zero-pads single-digit months and days', () => {
    expect(exportFilename(new Date(2026, 0, 5))).toBe('truss-printers-2026-01-05.json')
  })
})

describe('mergePrinters', () => {
  it('adds records that do not exist yet', () => {
    const outcome = mergePrinters(serializePrinters([X1C, VORON]), [])

    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.added).toEqual(['X1C', 'Voron 2.4'])
      expect(outcome.skipped).toEqual([])
      expect(outcome.merged).toEqual([X1C, VORON])
    }
  })

  it('keeps existing values and skips the conflict', () => {
    const stored: PrinterRecord = { name: 'X1C', extrapolationFactor: 1.5 }
    const outcome = mergePrinters(serializePrinters([X1C, VORON]), [stored])

    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.added).toEqual(['Voron 2.4'])
      expect(outcome.skipped).toEqual(['X1C'])
      // Existing values always win — the file's 1.0034 must not replace 1.5.
      expect(outcome.merged.find((r) => r.name === 'X1C')).toEqual(stored)
    }
  })

  it('treats a name clash as a clash regardless of case or whitespace', () => {
    const outcome = mergePrinters(
      serializePrinters([{ name: '  x1c ', extrapolationFactor: 2 }]),
      [X1C],
    )
    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.added).toEqual([])
      expect(outcome.skipped).toEqual(['x1c'])
    }
  })

  it('skips the second of two same-named records within one file', () => {
    const outcome = mergePrinters(
      serializePrinters([
        { name: 'X1C', extrapolationFactor: 1 },
        { name: 'x1c', extrapolationFactor: 2 },
      ]),
      [],
    )

    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.added).toEqual(['X1C'])
      expect(outcome.skipped).toEqual(['x1c'])
      expect(outcome.merged).toHaveLength(1)
      expect(outcome.merged[0].extrapolationFactor).toBe(1)
    }
  })

  it('is a no-op when exporting and immediately re-importing', () => {
    const existing = [VORON, X1C]
    const outcome = mergePrinters(serializePrinters(existing), existing)

    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.added).toEqual([])
      expect(outcome.skipped).toEqual(['Voron 2.4', 'X1C'])
      expect(outcome.merged).toEqual(existing)
    }
  })

  it('round-trips a full-precision factor without drift', () => {
    const factor = 137.4625 / 137.5
    const existing: PrinterRecord[] = [{ name: 'X1C', extrapolationFactor: factor }]

    const outcome = mergePrinters(serializePrinters([]), existing)
    expect(outcome.ok).toBe(true)

    const readBack = mergePrinters(serializePrinters(existing), [])
    expect(readBack.ok).toBe(true)
    if (readBack.ok) {
      expect(readBack.merged[0].extrapolationFactor).toBe(factor)
    }
  })

  it('accepts an empty file as a valid, empty merge', () => {
    const outcome = mergePrinters(serializePrinters([]), [X1C])

    expect(outcome.ok).toBe(true)
    if (outcome.ok) {
      expect(outcome.merged).toEqual([X1C])
      expect(outcome.added).toEqual([])
      expect(outcome.skipped).toEqual([])
    }
  })
})

describe('import refusals are distinct', () => {
  it('reports unparseable text as invalid-json', () => {
    expect(refusal('{ oops').kind).toBe('invalid-json')
  })

  it('reports an empty file as invalid-json rather than as an empty merge', () => {
    expect(refusal('').kind).toBe('invalid-json')
  })

  it('reports a non-object payload as not-an-object', () => {
    expect(refusal('[1,2,3]').kind).toBe('not-an-object')
    expect(refusal('"printers"').kind).toBe('not-an-object')
  })

  it('reports an unknown version as unsupported-version', () => {
    const result = refusal(JSON.stringify({ version: 2, printers: [] }))
    expect(result.kind).toBe('unsupported-version')
    if (result.kind === 'unsupported-version') {
      expect(result.detail).toContain('2')
    }
  })

  it('reports a missing printers array as malformed', () => {
    expect(refusal(JSON.stringify({ version: PAYLOAD_VERSION })).kind).toBe('malformed')
  })

  it('reports an unusable record as invalid-record and refuses the whole file', () => {
    const text = JSON.stringify({
      version: PAYLOAD_VERSION,
      printers: [X1C, { name: '', extrapolationFactor: 1 }],
    })
    const result = refusal(text, [])

    expect(result.kind).toBe('invalid-record')
    if (result.kind === 'invalid-record') {
      expect(result.detail).toContain('2')
    }
  })

  it.each([
    ['a non-numeric factor', { name: 'X', extrapolationFactor: '1.0' }],
    ['a zero factor', { name: 'X', extrapolationFactor: 0 }],
    ['a negative factor', { name: 'X', extrapolationFactor: -1 }],
    ['a missing factor', { name: 'X' }],
    ['a missing name', { extrapolationFactor: 1 }],
    ['a blank name', { name: '   ', extrapolationFactor: 1 }],
    ['a non-object record', 42],
  ])('refuses %s', (_label, record) => {
    const text = JSON.stringify({ version: PAYLOAD_VERSION, printers: [record] })
    expect(refusal(text).kind).toBe('invalid-record')
  })

  it('refuses an oversized payload without parsing it', () => {
    const text = 'x'.repeat(MAX_IMPORT_BYTES + 1)
    const result = refusal(text)

    expect(result.kind).toBe('too-large')
    if (result.kind === 'too-large') {
      expect(result.bytes).toBe(MAX_IMPORT_BYTES + 1)
      expect(result.limit).toBe(MAX_IMPORT_BYTES)
    }
  })

  it('accepts a payload exactly at the limit', () => {
    // Guards the boundary: the check is `>`, not `>=`.
    expect(mergePrinters(serializePrinters([]), []).ok).toBe(true)
    expect(isOversized(MAX_IMPORT_BYTES)).toBe(false)
    expect(isOversized(MAX_IMPORT_BYTES + 1)).toBe(true)
  })

  it('never applies a partial import', () => {
    const stored: PrinterRecord[] = [{ name: 'Existing', extrapolationFactor: 1 }]
    const text = JSON.stringify({
      version: PAYLOAD_VERSION,
      printers: [X1C, { name: 'Bad', extrapolationFactor: Infinity }],
    })

    // Infinity is not representable in JSON at all, so this arrives as null.
    const result = refusal(text, stored)
    expect(result.kind).toBe('invalid-record')
    if (result.kind !== 'too-large') {
      expect(result).not.toHaveProperty('merged')
    }
  })
})

/**
 * Asset sync (T11.1).
 *
 * Copies the two in-scope STLs from the repo root and re-encodes the referenced
 * documentation images into the app's source tree, so that Vite can emit them as
 * part of the module graph. The generated directories are gitignored: the repo
 * root stays the single source of truth, and committed copies could only drift.
 *
 * Why not `public/`: a public asset is referenced root-absolutely, which breaks
 * the moment the widget is embedded under a sub-path (PRD §6.3). Files that go
 * through the module graph are referenced relative to the app's own script URL
 * instead — see `src/assets/urls.ts`.
 *
 * Run with `pnpm assets:sync`; it is wired as `predev`/`prebuild`.
 */
import { existsSync } from 'node:fs'
import { copyFile, mkdir, readFile, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

const scriptDir = path.dirname(fileURLToPath(import.meta.url))
const appRoot = path.resolve(scriptDir, '..')
const repoRoot = path.resolve(appRoot, '..')

const config = JSON.parse(await readFile(path.join(appRoot, 'assets.config.json'), 'utf8'))

const stlSourceDir = path.resolve(repoRoot, config.stlSourceDir)
const imageSourceDir = path.resolve(repoRoot, config.imageSourceDir)
const stlOutputDir = path.resolve(appRoot, config.stlOutputDir)
const imageOutputDir = path.resolve(appRoot, config.imageOutputDir)

await mkdir(stlOutputDir, { recursive: true })
await mkdir(imageOutputDir, { recursive: true })

function human(bytes) {
  if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)}MB`
  return `${Math.round(bytes / 1024)}KB`
}

/** Fail loudly rather than shipping an app whose download button 404s. */
async function requireFile(source, role) {
  if (!existsSync(source)) {
    throw new Error(`Missing ${role}: ${source}`)
  }
  return stat(source)
}

const { maxEdge, quality } = config.image

let sourceBytes = 0
let outputBytes = 0
let optimised = 0
let copied = 0

for (const [key, fileName] of Object.entries(config.stl)) {
  const source = path.join(stlSourceDir, fileName)
  const target = path.join(stlOutputDir, `${key}.stl`)
  const info = await requireFile(source, 'STL')
  await copyFile(source, target)

  sourceBytes += info.size
  outputBytes += info.size
  copied += 1
}

for (const fileName of config.images) {
  const source = path.join(imageSourceDir, fileName)
  const target = path.join(imageOutputDir, `${path.parse(fileName).name}.webp`)
  const info = await requireFile(source, 'documentation image')

  const encoded = await sharp(source)
    // Honour EXIF orientation before resizing: a rotated phone photo otherwise
    // gets its long edge measured in the wrong direction.
    .rotate()
    .resize({ width: maxEdge, height: maxEdge, fit: 'inside', withoutEnlargement: true })
    .webp({ quality })
    .toBuffer()

  await writeFile(target, encoded)

  sourceBytes += info.size
  outputBytes += encoded.length
  optimised += 1
}

console.log(
  `assets:sync — ${copied} STLs copied, ${optimised} images optimised ` +
    `(${human(sourceBytes)} → ${human(outputBytes)} at ${maxEdge}px, WebP q${quality})`,
)

