import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'vite'
import { describe, expect, it } from 'vitest'

/**
 * Build-configuration test for the embedding requirement (T11.4, PRD §6.3).
 *
 * The requirement is that asset URLs resolve against the app's **own script
 * URL**, never the page or domain root — otherwise the widget works standalone
 * and breaks the instant it is mounted under a sub-path, which is precisely the
 * failure that would not be noticed until deployment.
 *
 * This builds the *real* asset module with the *real* config and then resolves
 * every emitted reference against a deliberately deep sub-path, so the test
 * fails for the same reason production would.
 */

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')

interface EmittedOutput {
  readonly fileName: string
  readonly type: string
  readonly code?: string
}

async function buildAssetModule(): Promise<readonly EmittedOutput[]> {
  const result = await build({
    root: appRoot,
    configFile: path.join(appRoot, 'vite.config.ts'),
    logLevel: 'error',
    build: {
      write: false,
      lib: {
        entry: path.join(appRoot, 'src/assets/urls.ts'),
        formats: ['es'],
        fileName: () => 'truss-calibrator-assets.js',
      },
    },
  })

  const outputs = Array.isArray(result) ? result[0].output : result.output
  return outputs as unknown as readonly EmittedOutput[]
}

/** `https://host/deep/sub/path/widget.js` — the sub-path mount we must survive. */
const HOST_SCRIPT_URL = 'https://example.com/deep/sub/path/truss-calibrator.js'
const HOST_SCRIPT_DIR = '/deep/sub/path/'

describe('emitted asset references', () => {
  it('are never root-absolute', async () => {
    const outputs = await buildAssetModule()
    const chunks = outputs.filter((output) => output.type === 'chunk')
    expect(chunks.length).toBeGreaterThan(0)

    for (const chunk of chunks) {
      const code = chunk.code ?? ''
      // A leading-slash reference would resolve against the host's origin.
      expect(code).not.toMatch(/["'(]\/[a-zA-Z0-9][^"')]*\.(stl|webp)/)
    }
  })

  it('emit the models and figures as real files, not inlined data URIs', async () => {
    const outputs = await buildAssetModule()
    const assets = outputs.filter((output) => output.type === 'asset').map((output) => output.fileName)

    expect(assets.filter((name) => name.endsWith('.stl'))).toHaveLength(2)
    expect(assets.filter((name) => name.endsWith('.webp'))).toHaveLength(28)
  })

  it('resolve inside the host script\u2019s own directory', async () => {
    const outputs = await buildAssetModule()
    const code = outputs
      .filter((output) => output.type === 'chunk')
      .map((output) => output.code ?? '')
      .join('\n')

    // The pattern Vite rewrites to: a *relative* path next to the emitted script.
    const references = [...code.matchAll(/["']([^"']+\.(?:stl|webp))["']/g)].map((match) => match[1])
    expect(references.length).toBeGreaterThan(0)

    for (const reference of references) {
      expect(reference.startsWith('/'), reference).toBe(false)
      expect(reference.startsWith('http'), reference).toBe(false)

      const resolved = new URL(reference, HOST_SCRIPT_URL)
      expect(resolved.origin).toBe('https://example.com')
      expect(resolved.pathname.startsWith(HOST_SCRIPT_DIR), reference).toBe(true)
    }
  })

  it('keeps `base` relative, which is what makes the above hold', async () => {
    // A guard on the configuration itself: with an absolute base Vite emits
    // `/assets/…` and every assertion above would fail.
    const { loadConfigFromFile } = await import('vite')
    const loaded = await loadConfigFromFile(
      { command: 'build', mode: 'production' },
      path.join(appRoot, 'vite.config.ts'),
      appRoot,
    )

    const config = loaded?.config as { base?: string } | undefined
    expect(config?.base).toBe('./')
  })
})

import { existsSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import assetsConfig from '../../assets.config.json'
import { IMAGES, STL, STL_DOWNLOAD_NAMES, type ImageKey } from './urls'

/**
 * The asset resolver's contract (T11.3) and its agreement with the pipeline that
 * produces the files (T11.1).
 *
 * The assertions are written against the *module's own URL* rather than against
 * a path literal, because that is the property under test: the widget must find
 * its assets relative to itself, whatever URL it is served from and whatever
 * sub-path it is mounted under.
 */

const MODULE_URL = new URL(import.meta.url)
const MODULE_DIRECTORY = new URL('.', import.meta.url).pathname
/** Vitest serves modules from the project root; `cwd` is that root. */
const projectRoot = process.cwd()

function resolved(url: string): URL {
  return new URL(url)
}

/** The on-disk path for an asset URL as resolved in the test environment. */
function diskPath(url: string): string {
  return path.join(projectRoot, resolved(url).pathname.replace(/^\//, ''))
}

/** Same origin and same directory as the script: not root-absolute, not borrowed. */
function expectBesideModule(url: string, directory: string, label: string): void {
  const target = resolved(url)
  expect(target.origin, label).toBe(MODULE_URL.origin)
  expect(target.pathname.startsWith(`${MODULE_DIRECTORY}${directory}/`), label).toBe(true)
}

describe('asset URLs', () => {
  it('resolves every image beside this module, never at the domain root', () => {
    for (const [key, url] of Object.entries(IMAGES)) {
      expectBesideModule(url, 'img', key)
      expect(resolved(url).pathname, key).toMatch(/\.webp$/)
    }
  })

  it('resolves both STLs beside this module', () => {
    for (const [key, url] of Object.entries(STL)) {
      expectBesideModule(url, 'stl', key)
      expect(resolved(url).pathname, key).toMatch(/\/stl\/[a-z]+\.stl$/)
    }
  })

  it('never resolves outside the app’s own directory', () => {
    for (const url of [...Object.values(IMAGES), ...Object.values(STL)]) {
      const target = resolved(url)
      expect(target.pathname).not.toMatch(/^\/[a-z]/i)
      expect(target.origin).toBe(MODULE_URL.origin)
    }
  })

  it('points at files the asset pipeline has actually produced', () => {
    for (const url of [...Object.values(IMAGES), ...Object.values(STL)]) {
      const file = diskPath(url)
      expect(existsSync(file), `${file} is missing — run pnpm assets:sync`).toBe(true)
    }
  })

  it('offers downloads under the guides’ own filenames', () => {
    expect(STL_DOWNLOAD_NAMES).toEqual({
      quad: 'Truss Calibration Beam Quad.stl',
      single: 'Truss Calibration Beam Single.stl',
    })
  })
})

describe('the resolver table and the pipeline manifest agree', () => {
  it('covers exactly the configured images', () => {
    const referenced = Object.values(IMAGES).map((url) =>
      path.basename(resolved(url).pathname, '.webp'),
    )
    const configured = assetsConfig.images.map((name) => path.parse(name).name)

    expect([...referenced].sort()).toEqual([...configured].sort())
  })

  it('has no two keys pointing at the same file', () => {
    expect(new Set(Object.values(IMAGES)).size).toBe(Object.keys(IMAGES).length)
  })

  it('never ships a deliberately excluded image', () => {
    const referenced = new Set(
      Object.values(IMAGES).map((url) => path.basename(resolved(url).pathname, '.webp')),
    )
    for (const excluded of assetsConfig.unused) {
      expect(referenced.has(path.parse(excluded).name), excluded).toBe(false)
    }
  })

  it('excludes the Dual model, which is out of scope', () => {
    expect(Object.keys(STL)).toEqual(['quad', 'single'])
    expect(JSON.stringify(assetsConfig.unused)).toContain('truss-dual')
  })

  it('types every referenced key', () => {
    const keys: ImageKey[] = ['trussQuad', 'xOuterDiagram', 'calipersIncorrectGap']
    for (const key of keys) {
      expect(IMAGES[key]).toBeTruthy()
    }
  })
})

