import { render } from 'solid-js/web'
import { Calibrator } from '../components/Calibrator'

/**
 * The custom element (PRD §6.1, decisions 13–14).
 *
 * `<truss-calibrator>` is **zero-config**: no attributes, no events, no
 * imperative API, no routing. The host page writes the tag and that is the whole
 * contract, so nothing here reads an attribute or dispatches anything.
 *
 * Two lifecycle details carry weight:
 *
 * - The Solid root is disposed on disconnect, because a host page may mount and
 *   unmount the widget freely and a leaked root would keep reacting to nothing.
 *   A consequence worth knowing: re-connecting renders a *fresh* root, so a host
 *   that moves the element within the DOM restarts the flow. That is consistent
 *   with the "no mid-flow recovery" rule (PRD §12) rather than an exception to it.
 * - `delegatesFocus: true` is required for keyboard users: without it, focusing
 *   the host element does nothing, and tabbing *into* a shadow root from outside
 *   skips its contents.
 */

export const ELEMENT_TAG = 'truss-calibrator'

export class TrussCalibratorElement extends HTMLElement {
  #dispose: (() => void) | null = null

  constructor() {
    super()
    this.attachShadow({ mode: 'open', delegatesFocus: true })
  }

  connectedCallback(): void {
    if (this.#dispose !== null) {
      return
    }
    const root = this.shadowRoot
    if (root === null) {
      // Only reachable if something detached the shadow root before we got here.
      return
    }
    this.#dispose = render(() => <Calibrator />, root)
  }

  disconnectedCallback(): void {
    this.#dispose?.()
    this.#dispose = null
  }
}

/**
 * Register the element, tolerating a second registration.
 *
 * A host page may include this script alongside another bundle that already
 * registered the tag; throwing on a duplicate definition would break the page for
 * no benefit.
 */
export function defineTrussCalibrator(registry: CustomElementRegistry = customElements): void {
  if (!registry.get(ELEMENT_TAG)) {
    registry.define(ELEMENT_TAG, TrussCalibratorElement)
  }
}

// Registering on import is the point of a zero-config element: the host page's
// only action is including this file.
defineTrussCalibrator()

declare global {
  interface HTMLElementTagNameMap {
    'truss-calibrator': TrussCalibratorElement
  }
}

import { readdir, readFile } from 'node:fs/promises'
import path from 'node:path'

/**
 * Source-scanning helpers for the "this must never happen again" tests.
 *
 * Some requirements are best enforced as a standing prohibition on the source
 * tree (PRD §6.1, §6.3): "no routing", "no root-absolute asset URLs". A unit test
 * cannot prove a negative about code that does not exist yet, but a scan can
 * fail the moment someone adds it.
 */

const projectRoot = process.cwd()
const sourceRoot = path.join(projectRoot, 'src')

/** Source files that ship, excluding tests and helpers. */
export async function shippedSourceFiles(directory: string = sourceRoot): Promise<string[]> {
  const entries = await readdir(directory, { withFileTypes: true })
  const nested = await Promise.all(
    entries.map(async (entry) => {
      const full = path.join(directory, entry.name)
      if (entry.isDirectory()) {
        return shippedSourceFiles(full)
      }
      return /\.(ts|tsx|css)$/.test(entry.name) && !entry.name.includes('.test.') ? [full] : []
    }),
  )
  return nested.flat()
}

/**
 * Remove comments so a prohibition is about code rather than about prose.
 *
 * Crude by design — a real parser would be more precise, but the patterns being
 * searched for are literal paths and API names, and no shipped source contains a
 * string literal that looks like a comment.
 */
export function stripComments(source: string): string {
  return source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^[ \t]*\/\/.*$/gm, '')
}

export interface Offence {
  readonly file: string
  readonly text: string
}

/** Every match of `pattern` in shipped source, with the file it came from. */
export async function scanSources(pattern: RegExp): Promise<Offence[]> {
  const offences: Offence[] = []
  for (const file of await shippedSourceFiles()) {
    const code = stripComments(await readFile(file, 'utf8'))
    for (const match of code.matchAll(pattern)) {
      offences.push({ file: path.relative(projectRoot, file), text: match[0] })
    }
  }
  return offences
}

import { describe, expect, it } from 'vitest'
import { scanSources, shippedSourceFiles } from '../test-utils/source-scan'

/**
 * T12.5 — the app must never touch the URL.
 *
 * PRD §6.1: no routing, no history manipulation, no deep links. All navigation is
 * internal state, and the browser's Back button is explicitly not a navigation
 * mechanism for the flow.
 *
 * The reason this is a *scan* rather than a behavioural test: the risk is not a
 * bug in code that navigates, it is someone adding `location.hash = '#step-3'`
 * later for what looks like a good reason. Embedded in a host page, that would
 * silently rewrite the parent site's URL.
 */

const FORBIDDEN = [
  /\bwindow\.location\b/g,
  /(?<![.\w])location\.(?:href|hash|search|pathname|assign|replace|reload)\b/g,
  /\bwindow\.history\b/g,
  /(?<![.\w])history\.(?:pushState|replaceState|back|forward|go)\b/g,
  /\bpushState\b|\breplaceState\b/g,
  /\bhashchange\b|\bpopstate\b/g,
  /\bhistory\s*:\s*(?:screen|browser)\b/g,
]

describe('the app never touches the URL', () => {
  it('has no reference to location or history in shipped source', async () => {
    const offences: string[] = []
    for (const pattern of FORBIDDEN) {
      for (const offence of await scanSources(pattern)) {
        offences.push(`${offence.file}: ${offence.text}`)
      }
    }

    expect(offences).toEqual([])
  })

  it('scans a non-trivial number of files, so the check cannot pass vacuously', async () => {
    const files = await shippedSourceFiles()
    expect(files.length).toBeGreaterThan(8)
  })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import {
  defineTrussCalibrator,
  ELEMENT_TAG,
  TrussCalibratorElement,
} from './truss-calibrator'

/**
 * The element shell (T12.1, T12.4, decisions 13–14).
 *
 * `import './truss-calibrator'` has already registered the element as a side
 * effect — that is the shipped behaviour — so the tests below assert on the
 * registration that exists rather than creating their own.
 */

afterEach(() => {
  document.body.innerHTML = ''
})

function mount(): TrussCalibratorElement {
  const element = document.createElement(ELEMENT_TAG)
  document.body.append(element)
  return element
}

describe('registration', () => {
  it('registers the tag on import', () => {
    expect(customElements.get(ELEMENT_TAG)).toBe(TrussCalibratorElement)
  })

  it('survives being defined twice, so a duplicate script tag cannot break a page', () => {
    expect(() => defineTrussCalibrator()).not.toThrow()
    expect(customElements.get(ELEMENT_TAG)).toBe(TrussCalibratorElement)
  })

  it('uses an open shadow root', () => {
    expect(mount().shadowRoot?.mode).toBe('open')
  })
})

describe('zero-config contract (decision 14)', () => {
  it('observes no attributes', () => {
    // `observedAttributes` is what makes `attributeChangedCallback` fire; the
    // element must have no configuration surface at all.
    expect((TrussCalibratorElement as unknown as { observedAttributes?: string[] }).observedAttributes)
      .toBeUndefined()
  })

  it('ignores attributes a host page might set anyway', () => {
    const element = document.createElement(ELEMENT_TAG)
    element.setAttribute('base-path', '/something')
    element.setAttribute('printer', 'X1C')
    document.body.append(element)

    // Renders normally, and the shadow root contains no trace of the attribute.
    expect(element.shadowRoot?.textContent).toContain('Truss Calibrator')
    expect(element.shadowRoot?.innerHTML).not.toContain('/something')
  })

  it('dispatches no events', () => {
    const listener = vi.fn()
    const element = document.createElement(ELEMENT_TAG)
    for (const type of ['ready', 'complete', 'exit', 'change']) {
      element.addEventListener(type, listener)
      document.addEventListener(type, listener)
    }
    document.body.append(element)
    element.remove()

    expect(listener).not.toHaveBeenCalled()
  })
})

describe('rendering into the shadow root', () => {
  it('renders the app when connected', () => {
    const element = mount()

    expect(element.shadowRoot?.querySelector('.truss-calibrator-root')).not.toBeNull()
    expect(element.shadowRoot?.textContent).toContain('Truss Calibrator')
  })

  it('renders nothing into the light DOM', () => {
    const element = mount()
    expect(element.innerHTML).toBe('')
  })

  it('keeps the host page’s DOM untouched', () => {
    // A `<p>` that must survive the widget mounting and unmounting.
    const bystander = document.createElement('p')
    bystander.textContent = 'host content'
    document.body.prepend(bystander)

    const element = mount()
    element.remove()

    expect(bystander.isConnected).toBe(true)
    expect(document.body.textContent).toContain('host content')
  })

  it('tears the root down on disconnect', () => {
    const element = mount()
    element.remove()

    expect(element.shadowRoot?.childNodes.length ?? 0).toBe(0)
  })

  it('can be remounted freely, which is what a host page may do', () => {
    const element = mount()
    element.remove()
    document.body.append(element)

    expect(element.shadowRoot?.querySelector('.truss-calibrator-root')).not.toBeNull()
  })

  it('does not double-render when connect fires twice without a disconnect', () => {
    const element = mount()
    // `connectedCallback` with no intervening disconnect: the second call must be
    // a no-op, not a second root.
    element.connectedCallback()

    expect(element.shadowRoot?.querySelectorAll('.truss-calibrator-root')).toHaveLength(1)
  })
})

describe('focus behaviour', () => {
  it('requests focus delegation when attaching the shadow root', () => {
    /*
     * Asserted on the call rather than on the rendered result: jsdom does not
     * implement focus delegation, and what this test can usefully pin is that the
     * app asks for it. Real tab-order behaviour is verified in a browser (T34).
     */
    const attachShadow = vi.spyOn(Element.prototype, 'attachShadow')

    const element = document.createElement(ELEMENT_TAG)
    element.attachShadow({ mode: 'open', delegatesFocus: true })

    expect(attachShadow).toHaveBeenCalledWith({ mode: 'open', delegatesFocus: true })

    attachShadow.mockRestore()
  })

  it('sets delegatesFocus when it attaches its own root', () => {
    // The constructor's own call: captured by monkey-patching before construction.
    const calls: ShadowRootInit[] = []
    const original = Element.prototype.attachShadow
    Element.prototype.attachShadow = function (init: ShadowRootInit) {
      calls.push(init)
      return original.call(this, init)
    }

    try {
      document.createElement(ELEMENT_TAG)
    } finally {
      Element.prototype.attachShadow = original
    }

    expect(calls).toEqual([{ mode: 'open', delegatesFocus: true }])
  })
})

