/*
 * App-private styles (T13.3, T13.4).
 *
 * `src/styles/**` is bundled into the custom element's shadow root, so nothing in
 * here can leak out to the host page and no host selector can reach in. Rules
 * that are genuinely reusable elsewhere belong in `global.css`/`elements/*`;
 * rules that only make sense for this app belong here.
 *
 * Two consequences of the shadow boundary are handled at the top of this file and
 * are easy to miss, because they are invisible in a page context:
 *
 * 1. A host page's `*, *::before, *::after { box-sizing: border-box }` reset does
 *    **not** reach inside a shadow root, so the app has to reset it itself. The
 *    element stylesheets assume border-box (full-width inputs with padding), so
 *    without this the layout is subtly wrong everywhere.
 * 2. Nothing in the host page constrains media or preformatted text inside the
 *    tree, so the app sets its own overflow guards. The mobile requirement is
 *    "must not break", and an unconstrained screenshot is the usual way a
 *    documentation-heavy flow breaks it.
 */

/* --- Resets the shadow boundary isolates us from --------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

:host {
  display: block;
  /* Fill and shrink with the host slot, but never overflow it. */
  max-width: 100%;
  min-width: 0;
  color: var(--text-color-default);
  font-family: var(--font-body);
  line-height: 1.5;
  /* Disables mobile "text inflation", which would otherwise resize our own type
     scale on a phone. */
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

/* --- Layout ---------------------------------------------------------------- */

.truss-calibrator-root {
  display: block;
  margin-inline: auto;
  padding: 0.5rem;
  max-width: 700px;
  /* Long words and URLs must wrap rather than widen the widget. */
  overflow-wrap: break-word;
}

.stack > * + * {
  margin-top: 1rem;
}

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
}

.measurement-grid {
  display: grid;
  gap: 0.75rem;
  /* Two up when there is room, one up on a phone. */
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
}

/* --- Overflow guards (mobile must not break) ------------------------------- */

img,
svg,
video,
canvas {
  display: block;
  max-width: 100%;
  height: auto;
}

pre,
code,
samp,
kbd,
table {
  max-width: 100%;
  overflow-x: auto;
}

/* --- Instructional media --------------------------------------------------- */

figure {
  margin: 0;
}

figure img {
  border-radius: var(--radius-medium);
  background-color: var(--form-background-color);
}

figcaption {
  font-size: 0.875rem;
  color: var(--text-color-deemphasized);
  margin-top: 0.25rem;
}

/* --- Controls -------------------------------------------------------------- */

/* The element stylesheets style text inputs and buttons but deliberately leave
   checkboxes and radios to the browser; at phone sizes the browser default is
   below a comfortable tap-target minimum, so the app sets it. */
input[type='checkbox'],
input[type='radio'] {
  inline-size: 1.25rem;
  block-size: 1.25rem;
  min-inline-size: 1.25rem;
  accent-color: var(--button-bg-primary);
  margin: 0;
  flex: none;
}

label.check {
  display: flex;
  gap: 0.625rem;
  align-items: flex-start;
  padding: 0.5rem 0;
  float: none;
  width: auto;
  cursor: pointer;
}

/* --- Numeric output -------------------------------------------------------- */

/* Tabular figures keep a column of measurements aligned digit-for-digit, which
   is the point of the details block: the user reads numbers off it. */
.numeric {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}

/* The transcribable hero: large, tabular digits that survive being read off one
   screen and typed into another (PRD §10). */
.readout {
  font-family: var(--font-headings);
  font-variant-numeric: tabular-nums;
  font-size: 2rem;
  font-weight: 600;
  color: var(--text-color-emphasis);
  letter-spacing: 0.01em;
  overflow-wrap: anywhere;
}

@media (max-width: 26rem) {
  .readout {
    /* Still comfortably legible at 320px, and never clipped. */
    font-size: 1.625rem;
  }
}

/* --- Messages -------------------------------------------------------------- */

.warning {
