    expect(code).toMatch(/:host\{[^}]*--form-input-padding/)
    expect(code).toMatch(/:host\{[^}]*--text-color-default/)
    // And no bare `:root{` selector may survive anywhere in the bundle.
    expect(code).not.toMatch(/[;{}]:root\{/)
  })

  it('carries the app’s own styles', async () => {
    const code = await builtBundle()
    expect(code).toContain('.truss-calibrator-root')
    expect(code).toContain('box-sizing:border-box')
  })

  it('emits no separate CSS file for the host page to link', async () => {
    const result = await build({
      root: appRoot,
      configFile: path.join(appRoot, 'vite.config.ts'),
      logLevel: 'silent',
      build: { write: false, minify: true },
    })
    if (!('output' in result)) {
