import { DESIGNED_LENGTH_MM } from './types'

/**
 * Measurement validation (PRD §8.3).
 *
 * Two tiers, and the distinction is the whole point:
 *
 * - **Blocking** — empty, non-numeric, ≤ 0, non-finite. Implemented by the
 *   reader in `math.ts`, because a value that is not a number cannot take part in
 *   arithmetic at all.
 * - **Non-blocking warnings** — plausible-range, ordering, divergence. These are
 *   *judgements about a number that is perfectly usable*, so they never stop the
 *   user: they say "this is probably a misread, look again". A warning that
 *   blocked progression would be a validation error wearing the wrong label, and
 *   the first time it was wrong the user would have no way past it.
 *
 * The thresholds are settled in PRD §8.3/§13.2 and the reasoning lives there; the
 * constants are named here so the copy and the rules cannot drift apart.
 */

/** Documented shrinkage is 0.95–0.99 of the 140mm beam, i.e. 133–138.6mm. */
export const PLAUSIBLE_MIN_MM = 133
export const PLAUSIBLE_MAX_MM = 138.6

/**
 * The inner and outer readings differ by the sum of two end-wall thicknesses —
 * under 1mm in the shipped designs. Twice that is unreachable by a correctly
 * seated caliper, and comfortably above every legitimate reading.
 */
export const MAX_DIVERGENCE_MM = 2

export type MeasurementWarningKind = 'implausible-length' | 'inner-not-smaller' | 'divergence'

export interface MeasurementWarning {
  readonly kind: MeasurementWarningKind
  readonly message: string
}

function implausibleLength(value: number): MeasurementWarning {
  return {
    kind: 'implausible-length',
    message:
      `A ${value}mm reading is unlikely: the beam is designed to be ${DESIGNED_LENGTH_MM}mm and ` +
      'shrinkage is normally 0.95–0.99 of that (133–138.6mm). Check the calipers and the units.',
  }
}

const INNER_NOT_SMALLER: MeasurementWarning = {
  kind: 'inner-not-smaller',
  message:
    'The inner reading is not smaller than the outer one. Both measure the same beam, so this ' +
    'means one of them was read or seated incorrectly.',
}

function divergence(gap: number): MeasurementWarning {
  return {
    kind: 'divergence',
    message:
      `Outer and inner differ by ${gap.toFixed(2)}mm, which is more than this design can produce ` +
      `(${MAX_DIVERGENCE_MM}mm). The calipers are probably not seated against the support walls — ` +
      'check the correct/incorrect examples before continuing.',
  }
}

/**
 * Warnings for one reading on its own.
 *
 * `null` means "nothing to say", which is the common case; an empty array is
 * never returned so callers cannot confuse "no warnings" with "not checked".
 */
export function checkReading(value: number): MeasurementWarning | null {
  if (value < PLAUSIBLE_MIN_MM || value > PLAUSIBLE_MAX_MM) {
    return implausibleLength(value)
  }
  return null
}

/**
 * Warnings for a completed axis: the ordering check and the divergence check.
 *
 * Both need both readings, so neither can be evaluated per-field — which is why
 * this takes the pair rather than one value.
 */
export function checkAxisPair(outer: number, inner: number): readonly MeasurementWarning[] {
  const warnings: MeasurementWarning[] = []

  if (inner >= outer) {
    warnings.push(INNER_NOT_SMALLER)
  } else if (outer - inner > MAX_DIVERGENCE_MM) {
    warnings.push(divergence(outer - inner))
  }

  const implausible = checkReading(outer) ?? checkReading(inner)
  if (implausible !== null) {
    warnings.push(implausible)
  }

  return warnings
}

/**
 * Warnings for a pair of *typed* values, tolerating either one being unusable.
 *
 * The pair checks need two numbers; while the user is still typing the second
 * one there is only one, and a half-entered pair must produce the single-field
 * warning rather than a spurious ordering complaint.
 */
export function typedPairWarnings(
  outerText: string,
  innerText: string,
  parse: (text: string) => { ok: true; value: number } | { ok: false },
): readonly MeasurementWarning[] {
  const outer = parse(outerText)
  const inner = parse(innerText)

  const warnings: MeasurementWarning[] = []
  if (outer.ok) {
    const warning = checkReading(outer.value)
    if (warning !== null) warnings.push(warning)
  }
  if (inner.ok) {
    const warning = checkReading(inner.value)
    if (warning !== null) warnings.push(warning)
  }
  if (outer.ok && inner.ok) {
    for (const warning of checkAxisPair(outer.value, inner.value)) {
      // The length warnings are already covered above; only the pair-specific
      // ones are added here, so one problem is never reported twice.
      if (warning.kind !== 'implausible-length') {
        warnings.push(warning)
      }
    }
  }

  return warnings
}

import { For, Show, type JSX } from 'solid-js'
import {
  announce,
  describedBy,
  FieldMessagesView,
  fieldIds,
  STEP_HEADING_ATTRIBUTE,
} from './a11y'
import { parseNumber } from '../domain/number'
import { typedPairWarnings, type MeasurementWarning } from '../domain/validation'

/**
 * The shared flow UI components (T16, PRD §9–§10).
 *
 * Built once, used by every step. The alternative — each step rolling its own
 * numeric input — is how a product acquires eight slightly different text boxes
 * with eight different warning behaviours, and the difference is only visible to
 * the user who hits the one that behaves differently.
 */

/* -------------------------------------------------------------------------- */
/* Step chrome (T16.1, T16.2)                                                  */
/* -------------------------------------------------------------------------- */

export interface StepChromeProps {
  /** 1-based position, for the progress indicator. */
  readonly position: number
  readonly total: number
  readonly title: string
  /** Whether Next may be pressed, and if not, why. */
  readonly gate: { readonly allowed: boolean; readonly reason: string | null }
  /** `null` on the first step, where the control means "leave the flow". */
  readonly back: (() => void) | null
  readonly next: () => void
  readonly exit: () => void
  /** Whether the exit confirmation is showing. */
  readonly exitRequested: boolean
  readonly confirmExit: () => void
  readonly cancelExit: () => void
  /** Hide the Next control on steps that leave through their own button. */
  readonly showNext?: boolean
  readonly nextLabel?: string
  readonly children: JSX.Element
}

/**
 * The frame every step renders inside: heading, progress, content, navigation.
 *
 * The heading carries `tabindex="-1"` and the step-heading marker, which is what
 * {@link focusStepHeading} targets — a step transition replaces the whole view,
 * so focus has to be moved deliberately or a keyboard user is left on a
 * destroyed element (PRD §6.4).
 */
export function StepChrome(props: StepChromeProps): JSX.Element {
  const reasonId = 'step-gate-reason'
  const blocked = () => !props.gate.allowed && props.gate.reason !== null

  return (
    <section class="stack" aria-label={props.title}>
      <p class="muted" data-testid="step-progress">
        Step {props.position} of {props.total}
      </p>

      <h2 tabindex="-1" {...{ [STEP_HEADING_ATTRIBUTE]: '' }}>
        {props.title}
      </h2>

      {props.children}

      <Show when={props.exitRequested}>
        <ExitConfirmation onConfirm={props.confirmExit} onCancel={props.cancelExit} />
      </Show>

      <div class="row">
        <Show when={props.back !== null} fallback={<button type="button" onClick={props.exit}>Exit</button>}>
          <button type="button" onClick={() => props.back?.()}>
            Back
          </button>
        </Show>

        <Show when={props.showNext ?? true}>
          <button
            type="button"
            onClick={props.next}
            disabled={!props.gate.allowed}
            aria-describedby={blocked() ? reasonId : undefined}
            data-testid="next"
          >
            {props.nextLabel ?? 'Next'}
          </button>
        </Show>
      </div>

      <Show when={blocked()}>
        <p class="muted" id={reasonId} data-testid="gate-reason">
          {props.gate.reason}
        </p>
      </Show>
    </section>
  )
}

/**
 * The exit confirmation (T15.4's rule, surfaced).
 *
 * Focus lands on **Stay**, not on the destructive action: a confirmation that
 * defaults to discarding measurements turns a stray Enter into data loss. The
 * measurements being discarded are eight caliper readings that cannot be
 * recovered — by design (PRD §12) — so the safe default matters more here than
 * the convenience of confirming with one keystroke.
 */
function ExitConfirmation(props: { onConfirm: () => void; onCancel: () => void }): JSX.Element {
  return (
    <div class="warning" role="group" aria-label="Confirm leaving the calibration" data-testid="exit-confirmation">
      <p>
        <strong>Leave the calibration?</strong> Your measurements will be discarded, and this flow
        does not save them (there is nothing to resume).
      </p>
      <div class="row">
        <button
          type="button"
          ref={(element) => element.focus()}
          onClick={props.onCancel}
          data-testid="stay"
        >
          Stay
        </button>
        <button type="button" onClick={props.onConfirm} data-testid="leave">
          Leave and discard
        </button>
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/* Checklist (T16.3)                                                           */
/* -------------------------------------------------------------------------- */

export interface CheckboxItem {
  /** The draft check key. */
  readonly key: string
  readonly label: string
  /** Optional explanatory text, associated with the checkbox. */
  readonly description?: string
}

export interface CheckboxGroupProps {
  readonly legend: string
  readonly items: readonly CheckboxItem[]
  readonly isChecked: (key: string) => boolean
  readonly onToggle: (key: string, checked: boolean) => void
}

/**
 * A group of checkboxes in a `fieldset`.
 *
 * The fieldset/legend pair is what gives the group an accessible name: a bare
 * list of checkboxes is announced as three unrelated controls, and the user never
 * hears what they are prerequisites *for*.
 */
export function CheckboxGroup(props: CheckboxGroupProps): JSX.Element {
  return (
    <fieldset>
      <legend>{props.legend}</legend>
      <For each={props.items}>
        {(item) => {
          const ids = fieldIds(`check-${item.key}`)
          return (
            <div>
              <label class="check" for={ids.control}>
                <input
                  id={ids.control}
                  type="checkbox"
                  checked={props.isChecked(item.key)}
                  aria-describedby={item.description === undefined ? undefined : ids.hint}
                  onChange={(event) => props.onToggle(item.key, event.currentTarget.checked)}
                />
                <span>{item.label}</span>
              </label>
              <Show when={item.description !== undefined}>
                <p class="muted" id={ids.hint}>
                  {item.description}
                </p>
              </Show>
            </div>
          )
        }}
      </For>
    </fieldset>
  )
}

/* -------------------------------------------------------------------------- */
/* Measurement field (T16.4)                                                   */
/* -------------------------------------------------------------------------- */

export interface MeasurementFieldProps {
  readonly id: string
  readonly label: string
  readonly value: string
  readonly onInput: (text: string) => void
  /** The sibling reading on the same axis, used for the pairing warnings. */
  readonly siblingText?: string
  readonly siblingLabel?: string
  /** Free-text hints or examples rendered under the label. */
  readonly hint?: string
}

/**
 * A numeric caliper reading.
 *
 * Everything about this component is about making one number trustworthy:
 *
 * - The parser accepts `,` or `.` and rejects half-typed values, so a partial
 *   edit reads as "not entered yet" rather than as a wrong number.
 * - A parse failure is **blocking** (`aria-invalid`, error text, alarm role).
 * - An implausible or inconsistent reading is a **warning** that never blocks —
 *   it is guidance, and a number that is merely unlikely must stay usable or the
 *   user would be stuck with no way forward.
 * - A warning that *appears* is announced once through the live region, because
 *   an inline warning is invisible to assistive technology otherwise. It is
 *   announced on appearance rather than on every keystroke: repeating it while
 *   the user edits would make it noise.
 */
export function MeasurementField(props: MeasurementFieldProps): JSX.Element {
  const ids = fieldIds(props.id)

  const parsed = () => parseNumber(props.value)
  const error = () => {
    if (props.value.trim() === '') {
      return null
    }
    const result = parsed()
    if (result.ok) {
      return result.value > 0 ? null : 'Enter a length greater than zero.'
    }
    return result.error.code === 'empty' ? null : `“${props.value.trim()}” is not a number.`
  }

  let lastAnnounced: string | null = null
  const warnings = (): readonly MeasurementWarning[] =>
    typedPairWarnings(
      // Either field may be the one being edited; the pair is always evaluated
      // from the pair's own perspective so both fields agree.
      props.siblingText === undefined ? props.value : props.label.includes('outer') ? props.value : props.siblingText,
      props.siblingText === undefined
        ? ''
        : props.label.includes('outer')
          ? props.siblingText
          : props.value,
      parseNumber,
    ).filter((warning) => warning.kind === 'implausible-length' && props.value.trim() !== '')

  const warningText = () => warnings()[0]?.message ?? null

  // Announce a *new* warning once; never re-announce the same one while typing.
  const announceIfNew = (message: string | null): void => {
    if (message !== null && message !== lastAnnounced) {
      announce(message)
    }
    lastAnnounced = message
  }

  return (
    <div class="stack">
      <label for={ids.control}>{props.label}</label>
      <Show when={props.hint !== undefined}>
        <p class="muted" id={ids.hint}>
          {props.hint}
        </p>
      </Show>
      <div class="row">
        <input
          id={ids.control}
          type="text"
          inputmode="decimal"
          autocomplete="off"
          value={props.value}
          aria-invalid={error() === null ? 'false' : 'true'}
          aria-describedby={describedBy(ids, { hint: props.hint, error: error(), warning: warningText() })}
          onInput={(event) => {
            props.onInput(event.currentTarget.value)
            announceIfNew(warningText())
          }}
        />
        <span class="muted" aria-hidden="true">
          mm
        </span>
      </div>
      <FieldMessagesView ids={ids} error={error()} warning={warningText()} />
    </div>
  )
}

