{"content":"import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'vite'
import { describe, expect, it } from 'vitest'

/**
 * The shipped bundle's stylesheet, not the source's (T13.1).
 *
 * This exists because of a real bug: the `:root` rewrite worked on the
 * unminified source and silently did nothing in the minified bundle, so every
 * design token was dropped and the widget rendered unstyled — in production only,
 * with the whole test suite green. The lesson is that "the stylesheet is
 * correct" has to be asserted against the artefact that ships.
 */

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')

let cached: string | null = null

async function builtBundle(): Promise<string> {
  if (cached !== null) {
    return cached
  }
  const result = await build({
    root: appRoot,
    configFile: path.join(appRoot, 'vite.config.ts'),
    logLevel: 'silent',
    build: { write: false, minify: true },
  })
  if (!('output' in result)) {
    throw new Error('Expected a completed build, received a watcher.')
  }
  const outputs = result.output as readonly { type: string; code?: string }[]
  cached = outputs
    .filter((output) => output.type === 'chunk')
    .map((output) => output.code ?? '')
    .join('\n')
  return cached
}

describe('the built bundle carries a usable stylesheet', () => {
  it('rewrites every page-level selector, minification included', async () => {
    const code = await builtBundle()

    // The design-token block must be reachable from inside the shadow root.
    expect(code).toMatch(/:host\{[^}]*--form-input-padding/)
    expect(code).toMatch(/:host\{[^}]*--text-color-default/)
    // And no bare `:root{` selector may survive anywhere in the bundle.
    expect(code).not.toMatch(/[;{}]:root\{/)
  })

  it('carries the app’s own styles', async () => {
    const code = await builtBundle()
    expect(code).toContain('.truss-calibrator-root')
    expect(code).toContain('box-sizing:border-box')
  })

  it('emits no separate CSS file for the host page to link', async () => {
    const result = await build({
      root: appRoot,
      configFile: path.join(appRoot, 'vite.config.ts'),
      logLevel: 'silent',
      build: { write: false, minify: true },
    })
    if (!('output' in result)) {
      throw new Error('Expected a completed build, received a watcher.')
    }
    const outputs = result.output as readonly { type: string; fileName: string }[]
    const css = outputs.filter((output) => output.fileName.endsWith('.css'))

    // The stylesheet travels inside the JS and is adopted by the shadow root; a
    // linked stylesheet could not reach it, and the host page would have to know
    // the file name.
    expect(css).toEqual([])
  })
})
