{"content":"import { mkdtemp, readdir, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { pathToFileURL, fileURLToPath } from 'node:url'
import { build } from 'vite'
import { afterAll, describe, expect, it } from 'vitest'

/**
 * The **shipped bundle**, mounted, with its stylesheet inspected (T13.1, T13.2).
 *
 * This test exists because of a real bug. The `:root` rewrite worked on the
 * unminified source and silently did nothing in the minified bundle — the
 * minifier emits `@import url(…);:root{…}`, where the preceding character is a
 * semicolon — so every design token was dropped and the widget rendered
 * unstyled in production, with the entire test suite green.
 *
 * Asserting on the source of the stylesheet cannot catch that. Loading the built
 * artefact into jsdom and reading the CSSOM can.
 */

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')

let buildDir: string | null = null
let loaded: Promise<void> | null = null

async function loadBuiltBundle(): Promise<void> {
  if (loaded !== null) {
    return loaded
  }
  loaded = (async () => {
    buildDir = await mkdtemp(path.join(tmpdir(), 'truss-build-'))
    const result = await build({
      root: appRoot,
      configFile: path.join(appRoot, 'vite.config.ts'),
      logLevel: 'silent',
      build: { outDir: buildDir, emptyOutDir: true, write: true, minify: true },
    })
    if (!('output' in result)) {
      throw new Error('Expected a completed build, received a watcher.')
    }
    const outputs = result.output as readonly { type: string; fileName: string }[]
    expect(outputs.filter((output) => output.fileName.endsWith('.css'))).toEqual([])

    await import(/* @vite-ignore */ pathToFileURL(path.join(buildDir, 'truss-calibrator.js')).href)
  })()
  return loaded
}

afterAll(async () => {
  if (buildDir !== null) {
    await rm(buildDir, { recursive: true, force: true })
  }
})

interface RuleSummary {
  readonly selector: string | null
  readonly text: string
}

function styleRules(root: ShadowRoot): RuleSummary[] {
  const style = root.querySelector('style')
  const sheet = style?.sheet
  if (sheet === null || sheet === undefined) {
    return []
  }
  return [...sheet.cssRules].map((rule) => ({
    selector: 'selectorText' in rule ? (rule as CSSStyleRule).selectorText : null,
    text: rule.cssText,
  }))
}

describe('the built bundle renders a styled widget', () => {
  it('defines the design tokens on :host, not on an unreachable :root', async () => {
    await loadBuiltBundle()

    const host = document.createElement('truss-calibrator')
    document.body.append(host)
    const rules = styleRules(host.shadowRoot!)

    const tokenRule = rules.find((rule) => rule.text.includes('--form-input-padding'))
    expect(tokenRule, 'no rule defines the design tokens').toBeDefined()
    expect(tokenRule?.selector).toContain(':host')

    // No rule may still be addressed to `:root`, which matches nothing inside a
    // shadow root: that is precisely the production failure this guards.
    expect(rules.filter((rule) => rule.selector === ':root')).toEqual([])

    host.remove()
  })

  it('carries the app’s own styles and the element styles it depends on', async () => {
    await loadBuiltBundle()

    const host = document.createElement('truss-calibrator')
    document.body.append(host)
    const selectors = styleRules(host.shadowRoot!).map((rule) => rule.selector)

    expect(selectors).toContain('.truss-calibrator-root')
    expect(selectors).toContain('.readout')
    expect(selectors?.some((selector) => selector?.includes('.mt-1'))).toBe(true)
    expect(selectors?.some((selector) => selector?.includes('button'))).toBe(true)

    host.remove()
  })

  it('applies the styles to the rendered tree', async () => {
    await loadBuiltBundle()

    const host = document.createElement('truss-calibrator')
    document.body.append(host)

    // The token reaches the host element, which is what makes every `var(--x)`
    // in the stylesheet resolve.
    const tokens = getComputedStyle(host).getPropertyValue('--text-color-default').trim()
    expect(tokens).toBe('#414141')

    host.remove()
  })

  it('ships one JS file and its assets, with no stylesheet for the page to link', async () => {
    await loadBuiltBundle()
    const files = await readdir(buildDir!)

    expect(files).toContain('truss-calibrator.js')
    expect(files.filter((name) => name.endsWith('.css'))).toEqual([])
  })
})
