/*
 * Labels must not float inside this app.
 *
 * The element stylesheets float every `label` and give it `width: 100%` — a
 * pattern that works in a light-DOM page, where the label is the last thing on
 * its line. Here it is actively broken: the float consumes the whole line, and
 * the `display: flex` row that follows it (which holds each measurement input
 * and its unit) establishes its own formatting context, so its *available* width
 * is zero. The input then renders at its intrinsic minimum — about 30px — and a
 * reading cannot be read or typed into it. Measured in a browser: a 30px input
 * at every viewport width, with the row reporting `width: 0`.
 *
 * `float: none` is correct for every label this app renders: they are all
 * block-level and own their line. (The per-component rules below, such as
 * `label.check`, already did this in one place; this makes it a property of the
 * app rather than of one component.)
 */
label {
  float: none;
}

.truss-calibrator-root {
  display: block;
  margin-inline: auto;
  padding: 0.5rem;
  max-width: 700px;
  /* Long words and URLs must wrap rather than widen the widget. */
  overflow-wrap: break-word;
}

/*
 * A field and its unit share the line: the input grows, `mm` sits after it.
 * Without this the input keeps `width: 100%` from the element stylesheet, fills
 * the flex line, and wraps the unit onto a line of its own.
 */
.row > input[type='text'] {
  flex: 1 1 auto;
  inline-size: auto;
