const result = await page.evaluate(() => {
  const sr = document.querySelector('truss-calibrator').shadowRoot
  const q = (sel) => sr.querySelector(sel)
  const log = []
  const heading = () => sr.querySelector('[data-step-heading]').textContent
  const click = (sel) => q(sel).click()
  const next = () => click('[data-testid="next"]')
  const tickAll = () => {
    for (const box of sr.querySelectorAll('input[type="checkbox"]')) {
      if (box.id !== 'dont-ask-again') box.click()
    }
  }
  const fill = (id, value) => {
    const el = q('#' + id)
    el.value = value
    el.dispatchEvent(new Event('input', { bubbles: true }))
  }
  const overflow = () => {
    const root = sr.querySelector('.truss-calibrator-root')
    const past = [...sr.querySelectorAll('*')].filter((el) => el.getBoundingClientRect().right > window.innerWidth + 1).length
    return `scroll=${root.scrollWidth}/${root.clientWidth} pastViewport=${past}`
  }

  // 1. Seed a printer by hand through the printer-data screen (the documented
  //    way in for a returning user).
  sr.querySelector('[data-testid="printers"]').click()
  sr.querySelector('[data-testid="add-printer"]').click()
  fill('printer-name', 'Rig One')
  fill('printer-factor', '0.9997272727')
  sr.querySelector('[data-testid="submit-printer"]').click()
  log.push(`printers: ${sr.querySelector('[data-testid="printer-list"]')?.textContent?.trim().slice(0, 40)}`)
  sr.querySelector('[data-testid="back-to-landing"]').click()

  // 2. The quick flow.
  sr.querySelector('[data-testid="start"]').click()
  tickAll()
  next()
  log.push(`C2: returning enabled=${!q('#branch-returning').disabled}`)
  click('#branch-returning')
  next()
  log.push(`S1: ${heading()} · ${overflow()}`)
  q('#pick-Rig One').click()
  next()
  log.push(`S2: ${heading()}`)
  tickAll()
  next()
  log.push(`S3: ${heading()} · ${overflow()}`)
  q('#single-sliced').click()
  next()
  q('#single-printed').click()
  next()
  log.push(`S5: ${heading()} · ${overflow()}`)
  fill('X-outer-input', '137.6')
  fill('X-inner-input', '137.4')
  next()
  log.push(`S6: ${heading()} · hero=${sr.querySelector('[data-testid="hero-percentage"]').textContent} · ${overflow()}`)
  log.push(`details: ${sr.querySelector('[data-testid="details"]').textContent.replace(/\s+/g, ' ').trim()}`)

